return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Catalan','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-12 17:46+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ca','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" guardat.','"%1$s" created. %2$d template updated.'=>'"%1$s" creat. %2$d plantilla actualitzada.' . "\0" . '"%1$s" creat. %2$d plantilles actualitzades.','"%s" created.'=>'"%s" creat.','"product" (replaces "article")'=>'"producte" (substitueix "article")','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Tractar H2 com equivalent a H1" (Configuració → SEO → Anàlisi): activa això quan el teu tema renderitza el títol de la publicació dins d’un H2 en lloc d’un H1. L’anàlisi promou el primer H2 a H1 perquè la puntuació no sigui penalitzada incorrectament.','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d caràcters — bo, lleugerament per sobre de l\'ideal %2$d però dins de l\'interval acceptat de %3$d caràcters. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d caràcters — longitud ideal. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d caràcters — probablement truncat en els SERPs (mantingueu-lo per sota de %2$d). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d caràcters — massa curt (apunta a %2$d–%3$d). %4$s','%1$d chars, %2$d words — good title.'=>'%1$d caràcters, %2$d paraules — bon títol.','%1$d internal, %2$d external.'=>'%1$d intern, %2$d extern.','%1$d of %2$d image(s) missing alt text.'=>'%1$d de %2$d imatges sense text alternatiu.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d publicació etiquetada amb _lf_lang = %2$s.' . "\0" . '%1$d publicacions etiquetades amb _lf_lang = %2$s.','%1$d translated, %2$d skipped.'=>'%1$d traduït, %2$d saltat.','%1$d words — below recommended minimum of %2$d.'=>'%1$d paraules — per sota del mínim recomanat de %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d paraules — contingut molt prim. Considereu ampliar a almenys %2$d paraules.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d ja traduït — <a href="#" class="lf-force-translate">forçar la re-traducció</a>','%d external link(s), no internal links.'=>'%d enllaç(s) externs, cap enllaç intern.','%d external link(s), no internal links. Add internal links to related content.'=>'%d enllaç(s) externs, cap enllaç intern. Afegeix enllaços interns a contingut relacionat.','%d H1 tags found — a page should have exactly one H1.'=>'%d etiquetes H1 trobades — una pàgina hauria de tenir exactament una H1.','%d image(s), all have alt text.'=>'%d imatge(s), totes tenen text alternatiu.','%d label(s) translated.'=>'%d etiquet(es) traduïda(s).','%d language not yet linked'=>'%d idioma sense enllaç encara' . "\0" . '%d idiomes sense enllaç encara','%d link updated.'=>'%d enllaç actualitzat.' . "\0" . '%d enllaços actualitzats.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'No s\'ha pogut eliminar automàticament %d arxiu(s) de localització (DISALLOW_FILE_MODS està activat). Elimina-ho manualment a través del teu servidor o WP-CLI: wp language core uninstall <locale>' . "\0" . 'No s\'han pogut eliminar automàticament %d arxiu(s) de localització (DISALLOW_FILE_MODS està activat). Elimina-ho manualment a través del teu servidor o WP-CLI: wp language core uninstall <locale>','%d locale file removed.'=>'Arxiu(s) de localització eliminat(s).' . "\0" . 'Arxius de localització eliminats.','%d locale pack installed.'=>'Paquet de localització instal·lat.' . "\0" . 'Paquets de localització instal·lats.','%d navigation reference updated.'=>'Referència de navegació actualitzada.' . "\0" . 'Referències de navegació actualitzades.','%d part reference updated.'=>'Referència de part actualitzada.' . "\0" . 'Referències de parts actualitzades.','%d post'=>'%d publicació' . "\0" . '%d publicacions','%d rule registered'=>'%d regla registrada' . "\0" . '%d regles registrades','%d template repaired.'=>'%d plantilla reparada.' . "\0" . '%d plantilles reparades.','%d term(s) translated.'=>'%d terme(s) traduït(s).','%d words.'=>'%d paraules.','%s Archive'=>'%s Arxiu','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s està actiu i ja genera JSON-LD de Schema.org. Lingua Forge ha desactivat la seva pròpia sortida de esquema per evitar gràfics en conflicte. A diferència d\'Open Graph — on LF afegeix og:locale a més del sortida d\'un altre plugin — l\'esquema no pot ser complementat netament: gràfics JSON-LD duplicats o que s\'overlapen produeixen errors de validació. Desactiva la sortida de esquema en el plugin detectat si vols que LF gestioni dades estructurades.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s està actiu i genera el seu propi mapa del lloc. Aquest mapa del lloc és separat del de LF. Tots dos s\'han de presentar a Google Search Console: el mapa del lloc del plugin SEO llista el teu contingut; el mapa del lloc de LF afegeix els enllaços alternatius multilingües. El mapa del lloc de LF s\'anuncia automàticament en robots.txt.','(active)'=>'(actiu)','(avg %.1f hits/block)'=>'(mitjana %.1f visites/bloc)','(avg %.1f hits/entry)'=>'(mitjana %.1f visites/entrada)','(classic theme)'=>'(tema clàssic)','(disabled)'=>'(desactivat)','(FSE / block theme)'=>'(tema FSE / bloc)','(no title) #%d'=>'(sense títol) #%d','(partial)'=>'(parcial)','(server/FPM timeout still applies)'=>'(el temps d’espera del servidor/FPM encara s’aplica)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} no tenia enllaços reemplaçables — reescaneja per investigar)','.txt file(s) in the directory'=>'arxiu(s) .txt a la carpeta','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — no s\'han trobat H2 o H3 subtítols. Afegir H2s millora l\'estructura.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — sense subtítols H2 (acceptable per a aquest tipus de contingut).','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — sense H2, però s’han trobat %d subtítols H3 (p. ex. capçaleres d’acordió/detalls). La estructura és acceptable.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — contingut curt (%d paràgrafs), no es requereixen subtítols.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d plantilla(s) localitzada(s) del tema &#8220;%2$s&#8221; es conserven a la base de dades però actualment estan inactives. Tornaran a estar actives si reactives aquest tema. Per portar les teves traduccions al nou tema, regenerar-les a través de <strong>Configuració → Lingua Forge → Router → Fesca de FSE</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> enllaç(s) que es poden arreglar automàticament','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> enllaç(s) que necessiten revisió manual','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> camí(s) obsolet(s)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problema(s) de plantilla','_lf_lang Coverage'=>'Cobertura _lf_lang','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Existeix un fitxer robots.txt físic al directori arrel del lloc. El robots.txt virtual de WordPress — i el filtre Sitemap de LF — són evitats. El sitemap de LF no s\'anuncia als motors de cerca.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepta només arxius .mo compilats. El nom de l\'arxiu ha de seguir el patró {textdomain}-{locale}.mo. Carregar un arxiu amb el mateix nom que un de ja existent el substituirà.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Accés prohibit — el teu compte pot estar suspès o la clau no té els permisos necessaris.','Action'=>'Acció','active'=>'actiu','Active Languages'=>'Idiomes actius','Active languages'=>'Idiomes actius','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Idiomes actius: afegeix cada idioma que vulguis suportar. Cada idioma obté un prefix d\'URL o un subdomini i una etiqueta hreflang a la capçalera de la pàgina.','Active Plugins'=>'Plugins actius','Active preset'=>'Preestablert actiu','Active Provider'=>'Proveïdor actiu','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Proveïdor actiu, claus configurats, seleccions de nivell de model, predefinit i quota diària.','Active theme'=>'Tema actiu','Active: %s.'=>'Actiu: %s.','Add entry'=>'Afegeix entrada','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Afegeix instruccions per millorar l\'esborrany — per exemple, fer-lo més curt, afegir una secció de conclusió, utilitzar un registre més formal, incloure un bloc de preguntes freqüents…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Afegeix instruccions per millorar l\'esborrany — per exemple, fer-lo més curt, afegir una secció de conclusió, utilitzar un registre més formal…','Add key →'=>'Afegeix clau →','Add new entry'=>'Afegeix una nova entrada','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Afegeix un terme per fila. Tant el terme d\'origen com la traducció són obligatoris. El parell de llengües determina a quines tasques de traducció s\'aplica la restricció.','Add Sitemap directive to robots.txt'=>'Afegeix la directiva Sitemap al robots.txt','Add the following line to your robots.txt manually:'=>'Afegeix la següent línia al teu robots.txt manualment:','Add WooCommerce product tags to Open Graph output'=>'Afegeix etiquetes de producte de WooCommerce a la sortida de Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Afegeix un enllaç a la pàgina d\'inici perquè els visitants puguin navegar en la seva llengua.','Administrators only (manage_options)'=>'Només administradors (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Després de canviar la llengua principal, actualitza els enllaços permanents (secció inferior) perquè s\'actualitzi la ruta de les URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Després de canviar la configuració de l\'estructura de URL (prefix de camí ↔ subdomini), visita sempre Configuració → Enllaços permanents i fes clic a Desa els canvis per actualitzar les regles de reescriptura.','AI analysis failed. Please try again.'=>'L\'anàlisi d\'IA ha fallat. Torna-ho a provar.','AI Behaviour Preset'=>'Predefinit de comportament d\'IA','AI cache cleared. %d entry was removed.'=>'Caché d\'IA buidada. %d entrada s\'ha eliminat.' . "\0" . 'Caché d\'IA buidada. %d entrades s\'han eliminat.','AI Configuration'=>'Configuració d\'AI','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Les funcions d\'IA són opcionals. La ruta de llengua, hreflang, el canviador de llengua i el sistema de grups de traducció funcionen sense un proveïdor configurat.','AI Limits & Security'=>'Límites i seguretat d\'IA','AI Provider'=>'Proveïdor d\'IA','AI provider returned an empty response.'=>'El proveïdor d\'IA ha retornat una resposta buida.','AI Provider Tab'=>'Pestanya del Proveïdor AI','AI Recommendations'=>'Recomanacions d\'IA','AI returned an unexpected response format. Please try again.'=>'L\'IA ha retornat un format de resposta inesperat. Torna-ho a provar.','AI translation and batch analysis may time out. Recommend 120s or more.'=>'La traducció AI i l\'anàlisi per lots poden caducar. Recomanat 120s o més.','AI Usage'=>'Ús d\'IA','AI Usage & Cache'=>'Ús d\'IA i caché','AI Usage & Cache Tab'=>'Pestanya d\'Ús AI i Cache','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Apunta a 120–160 caràcters. Deixa-ho buit per utilitzar el fallback de l\'extracte.','All labels already translated.'=>'Totes les etiquetes ja estan traduïdes.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Tots els motors de cerca principals — Google, Bing i Yandex — descobreixen el sitemap automàticament mitjançant la directiva Sitemap: al robots.txt. No cal cap acció manual. Els botons de baix envien un ping immediat perquè el motor recarregui el sitemap ara en lloc d\'esperar la seva pròxima revisió programada del robots.txt.','All published posts have a _lf_lang value. No gaps detected.'=>'Totes les publicacions publicades tenen un valor _lf_lang. No s\'han detectat gaps.','All template metadata is already up to date.'=>'Totes les metadades de la plantilla ja estan actualitzades.','All time'=>'Tot','All types'=>'Tot tipus','Allow editors to lock individual blocks'=>'Permet als editors bloquejar blocs individuals','Allow Gutenberg template-editing mode on post screens'=>'Permet el mode d\'edició de plantilles de Gutenberg a les pantalles de publicació','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'També elimina les assignacions de llengua, les relacions de traducció, les metadescripcions, el glossari i la Memòria de Traducció quan s\'desinstal·la el plugin','Also generate meta description'=>'També genera metadescripció','Alternative (server-side):'=>'Alternativa (del costat del servidor):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Emet sempre només og:locale i og:locale:alternate. Utilitza quan un altre plugin o tema gestiona el conjunt complet d\'OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Emet sempre el conjunt complet d\'OG + Targeta de Twitter independentment d\'altres plugins. Utilitza-ho només si cap altre plugin mostra etiquetes OG.','An unknown error occurred.'=>'S\'ha produït un error desconegut.','Analyse'=>'Analitza','Analyse all languages'=>'Analitza totes les llengües','Analyse…'=>'Anàlisi…','Analysis'=>'Anàlisi','Analysis request failed. Please try again.'=>'La sol·licitud d\'anàlisi ha fallat. Torna-ho a provar.','Analyzing…'=>'Analitzant…','and'=>'i','and set it to one of the active content languages listed above.'=>'i configurar-lo en una de les llengües de contingut actives que es mostren a dalt.','Anthropic (Claude)'=>'Anthropic (Claude)','Anthropic Console'=>'Consola d’Anthropic','any'=>' qualsevol','API calls saved by cache'=>'Crides API desades per la memòria cau','API Key'=>'Clau API','API Keys'=>'Claus API','API Response Cache'=>'Memòria cau de respostes API','API Response Cache setting saved.'=>'Configuració de la memòria cau de respostes API guardada.','Appends the following line to your existing robots.txt: %s'=>'Afegeix la següent línia al teu fitxer robots.txt existent: %s','Applied ✓'=>'Aplicat ✓','Apply failed — please try again.'=>'L\'aplicació ha fallat — si us plau, torna-ho a provar.','Apply to all language versions'=>'Aplica a totes les versions de llengua','Apply to Block'=>'Aplicar al bloc','Apply to Editor'=>'Aplicar a l\'editor','Apply to Footnote'=>'Aplicar a la nota al peu','Apply to Meta Description'=>'Aplicar a la meta descripció','Apply translation'=>'Aplicar traducció','Applying…'=>'Aplicant…','Approximate size'=>'Tamany aproximat','Archive'=>'Arxiu','Archive: %s'=>'Arxiu: %s','Article / WebPage'=>'Article / Pàgina web','Article / WebPage — all singular posts and pages'=>'Article / Pàgina web — totes les publicacions i pàgines en singular','Attribute label displayed in this language. Leave empty to use the default label.'=>'Etiqueta d\'atribut mostrada en aquesta llengua. Deixa-ho buit per utilitzar l\'etiqueta per defecte.','Authors and above (edit_published_posts)'=>'Autors i més (edit_published_posts)','Auto (recommended)'=>'Automàtic (recomanat)','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'L\'auto-detecta assigna: productes WooCommerce → perfil de producte; la pàgina d\'inici estàtica → perfil de destinació; tot el demés → perfil de bloc. Tria un perfil específic per substituir això per a totes les publicacions.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Auto-detectat per a la pàgina estàtica; es pot seleccionar manualment. Títol 20 pts · Meta descripció 30 pts · Comptador de paraules 15 pts · Encabezaments 10 pts · Imatges 15 pts · Enllaços 0 pts. Límits de SERP per al títol 70 caràcters; avís de comptador de paraules per sota de 150, error per sota de 60; H2 i enllaços interns opcionals.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Auto-detectat per a productes de WooCommerce. Títol 20 pts · Meta descripció 30 pts · Comptador de paraules 15 pts · Encabezaments 5 pts · Imatges 20 pts · Enllaços 0 pts. Límits de SERP per al títol 70 caràcters; avís de comptador de paraules per sota de 80, error per sota de 40; H2 i enllaços interns opcionals.','Available models reference'=>'Referència de models disponibles','avg'=>'mitjana','Batch Analysis'=>'Anàlisi per lots','Behavior'=>'Comportament','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Comportament: escull el preset d\'IA (Literal, Equilibrat, Creatiu), afegeix instruccions personalitzades per a tot el lloc, habilita o deshabilita la traducció automàtica després de desar la publicació, i configura la Memòria de Traducció.','Block Content'=>'Contingut del bloc','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Mostra un avís cortès quan la pàgina actual es mostra en la seva llengua d\'origen perquè no existeix traducció per a la llengua del visitant. Impulsat pel senyal LINGUAFORGE_LANG_FALLBACK_ACTIVE del router Lingua Forge — no emet res quan existeix una traducció per a la localització de la sol·licitud.','Block Editor'=>'Editor de blocs','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'idioma','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'traducció','Block locking'=>'Bloqueig de blocs','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patrons de blocs registrats per a tipus de publicació personalitzats. Utilitza el botó de Traducció per produir una variant en un idioma. El contingut traduït s\'hi desa i es pot copiar en qualsevol publicació CPT des de l\'inseridor de patrons del editor de blocs o utilitzar com a punt de partida per a un Patró sincronitzat (Bloc reutilitzable).','block titleMissing Translation Notice'=>'Avís de traducció manca','Block translation reuses'=>'Reutilitzacions de traducció de blocs','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Caché de traducció a nivell de bloc compartida entre publicacions. Quan està activat, blocs idèntics (mateix markup, parella de llengua i glossari) es serveixen des de la memòria en lloc de cridar a l\'AI de nou. Les edicions de glossari i els canvis en el preset de compliment invaliden automàticament les traduccions en caché afectades.','Blog / Editorial'=>'Bloc / Editorial','Blog / Editorial (default)'=>'Blog / Editorial (per defecte)','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Les publicacions del blog utilitzen Article; totes les altres tipus de publicacions i pàgines utilitzen WebPage. Inclou titular, descripció, inLanguage, url, datePublished, dateModified, imatge, i editor.','Browser language redirect'=>'Redirecció segons la llengua del navegador','Built-in preset instructions:'=>'Instruccions predefinides integrades:','Bulletize (•-prefixed)'=>'Bulletize (prefixed amb •)','cached'=>'en memòria','Cached API responses'=>'Respostes API en memòria','Cached block translations'=>'Traduccions de blocs en memòria','Cancel'=>'Cancel·la','Cannot determine target language from slug.'=>'No es pot determinar la llengua objectiu a partir de l\'slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'No es pot escriure al producte %1$d: és una versió traduïda (idioma: %2$s)%3$s. Les dades operatives (preu, estoc, SKU, dimensions) s\'han d\'actualitzar al producte original. Resol l\'ID del producte original a través de: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Etiqueta canònica','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita l\'ús d\'IA que pot generar el lloc i restringeix quins rols d\'usuari poden activar trucades d\'IA de pagament. S\'ubica per sobre del límit de taxa per usuari (30 sol·licituds / minut, codificat) que ja protegeix contra bucles descontrolats d\'un sol usuari.','Cart'=>'Carro','chars'=>'caràcters','Check your account, billing, or remaining credits directly on the provider console:'=>'Revisa el teu compte, facturació o crèdits restants directament a la consola del proveïdor:','Checkout'=>'Finalització de compra','Chunk translated'=>'Fragment traduït','Chunk translated to:'=>'Fragment traduït a:','Clear'=>'Netejar','Clear All'=>'Netejar tot','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Netejar la memòria cau de respostes de l\'AI? Les futures sol·licituds desencadenaran noves trucades a l\'API fins que la memòria cau es reconstruïsca.','Clear API Response Cache'=>'Netejar la memòria cau de respostes de l\'API','Clear Debug Files'=>'Netejar arxius de depuració','Clear hints'=>'Netejar pistes','Clear input'=>'Netejar entrada','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Netejar la memòria de traducció completa? Les traduccions futures reconstruiran la memòria cau a mesura que s\'executen.','Clear Translation Memory'=>'Netejar la memòria de traducció','Close'=>'Tancar','Close language panel'=>'Tancar panell de llengua','Close popover'=>'Tancar popover','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Descàrrega col·lapsable de totes les entrades propietat de LF a $wp_rewrite->extra_rules_top. Útil per diagnosticar errors 404 o conflictes de rutes després d\'afegir una nova llengua.','Compatibility'=>'Compatibilitat','Compliance Preset'=>'Predefinit d\'compliment','Configuration issue: WP site language is not a content language'=>'Problema de configuració: l\'idioma del lloc WP no és una llengua de contingut.','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Configura un proveïdor d\'AI a Configuració → Clau API per habilitar recomanacions amb IA.','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Configura hreflang, Open Graph, Schema.org, mapes del lloc i compartició social per a cada idioma del teu lloc. Cada secció a continuació gestiona un aspecte del SEO multilingüe.','Configured'=>'Configurat','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Confirma que l\'estructura del permalink és compatible amb el ruteig de camins de Lingua Forge. Les estructures simples i només numèriques no són compatibles.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contacta amb el formulari 7 (wpcf7_contact_form), contactes Flamingo i missatges entrants (flamingo_contact, flamingo_inbound), i l\'emmagatzematge de sincronització de paquets d\'idioma de WordPress (wp_sync_storage) s\'exclouen automàticament. Afegeix qualsevol altre tipus de publicació de tercers que no hagi de filtrar per idioma, una per línia o separada per comes.','Content generated'=>'Contingut generat','Content Generator'=>'Generador de contingut','Content profiles and weights'=>'Perfils de contingut i pesos','Content ready'=>'Contingut preparat','Contributors and above — default (edit_posts)'=>'Col·laboradors i més — per defecte (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controla quanta informació s\'envia a l\'IA i la mida de la resposta. Deixa un camp en blanc per utilitzar el valor predefinit integrat (mostrat com a espai reservat). Augmenta aquests valors si es tallen pàgines grans; redueix-los per reduir els costos de l\'API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla el pressupost de tokens i els límits d\'entrada per a la funció Generador de contingut amb IA. Deixa els camps en blanc per utilitzar els valors predefinits.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla què passa quan un administrador elimina el plugin des de Plugins → Plugins instal·lats → Elimina. Els ajustaments del plugin i les memòries cau de l\'IA sempre s\'eliminan. Les assignacions de llengua i les relacions de traducció es mantenen per defecte perquè una desinstal·lació accidental o una reinstal·lació puguin continuar on ho van deixar.','Conversational'=>'Conversacional','Copied ✓'=>'Copiat ✓','Copied!'=>'Copiat!','Copy'=>'Copiar','Copy and paste into a GitHub issue or support request.'=>'Copia i enganxa en un problema de GitHub o sol·licitud de suport.','Copy failed — please copy the URL manually.'=>'Error en copiar — si us plau, copia l\'URL manualment.','Copy markup'=>'Copiar marca','Copy system info'=>'Copia la informació del sistema','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Copia l\'URL actual al porta-retalls. Mostra un missatge de "Enllaç copiat" en èxit.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Copia el resultat i enganxa\'l on sigui necessari (per exemple, directament al camp de nota a peu de pàgina).','Copy to safe storage'=>'Copia a emmagatzematge segur','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'accions JS copy/native/auto: gestionat per LF\'s social-share.js','Could not add entry: source term and target term are required.'=>'No s\'ha pogut afegir l\'entrada: cal el terme d\'origen i el terme de destinació.','Could not copy the file. Check that the uploads folder is writable.'=>'No s\'ha pogut copiar l\'arxiu. Comprova que la carpeta d\'uploads sigui editable.','Could not instantiate the provider.'=>'No s\'ha pogut instanciar el proveïdor.','Could not save the file. Check that the uploads folder is writable.'=>'No s\'ha pogut desar l\'arxiu. Comprova que la carpeta d\'uploads sigui editable.','Could not save the glossary entry.'=>'No s\'ha pogut desar l\'entrada del glossari.','Could not write to robots.txt. Check file permissions.'=>'No s\'ha pogut escriure a robots.txt. Comprova els permisos del fitxer.','CPT Block Patterns'=>'Patrons de blocs CPT','Create'=>'Crear','Create missing'=>'Crear missing','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Crear traduccions per al tipus de publicació "%s" requereix una integració activa. Assegura\'t que la integració requerida estigui instal·lada i activa.','Creating…'=>'Creant…','Creative / Marketing'=>'Creatiu / Màrqueting','Creative / Marketing instructions'=>'Instruccions creatives / de màrqueting','Current content (will be overwritten)'=>'Contingut actual (s\'escriurà per sobre)','Current status'=>'Estat actual','Current title'=>'Títol actual','Current: {current}'=>'Actual: {current}','Currently emitting'=>'Actualment emetent','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Actualment heretat de la constant %s. Seleccionar un valor aquí el sobrescriurà.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Actualment s\'ignora per a les publicacions que utilitzen espais reservats d\'atribut de comentari de bloc (campos wp:details summary, etc.) — passen a la ruta de traducció de trucada única existent.','Currently:'=>'Actualment:','Custom'=>'Personalitzat','Custom tables — LF post-meta filters do not affect orders.'=>'Taules personalitzades — els filtres de metadades LF no afecten les comandes.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'S\'ha assolit la quota diària d\'AI (%1$d sol·licituds). Es reinicia a les %2$s UTC.','Daily quota'=>'Quota diària','Daily request limit'=>'Límit diari de sol·licituds','Danger Zone'=>'Zona de perill','Debug Files'=>'Arxius de depuració','Debug files cleared. %d file was removed.'=>'Arxius de depuració eliminats. S\'ha eliminat %d arxiu.' . "\0" . 'Arxius de depuració eliminats. S\'han eliminat %d arxius.','Debug Info'=>'Informació de depuració','Debug logging'=>'Registre de depuració','Debug logging disabled.'=>'Registre de depuració desactivat.','Debug logging enabled.'=>'Registre de depuració activat.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Depuració: activa el registre de depuració per capturar les sol·licituds d\'AI i les respostes de l\'API en un arxiu local. Desactiva després de la solució de problemes — el mode de depuració escriu un arxiu en cada sol·licitud d\'AI.','Default OG image'=>'Imatge OG per defecte','Default profile'=>'Perfil per defecte','Delete'=>'Suprimir','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Suprimir tots els arxius .txt del directori de depuració? El directori en si romandrà, de manera que les futures escriptures de depuració encara arribaran netes.','Delete all files for this override (both .mo and .po)?'=>'Suprimir tots els arxius d\'aquesta substitució (tant .mo com .po)?','Delete content data on uninstall'=>'Suprimir dades de contingut en desinstal·lació','Delete this glossary entry?'=>'Suprimir aquesta entrada del glossari?','Describe what to write — topic, key points, structure…'=>'Descriu què escriure — tema, punts clau, estructura…','Destructive action — read before proceeding'=>'Acció destructiva — llegir abans de continuar','Details ↗'=>'Detalls ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Detecta plugins SEO actius (Yoast, Rank Math, etc.) en temps d\'execució. Emite només og:locale + og:locale:alternate quan un altre plugin ja emet el conjunt complet d\'OG; emet el conjunt complet quan cap no és detectat.','Directory'=>'Directori','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Desactiva només per a llocs sense cap o quan implementes hreflang completament personalitzat. Quan està desactivat, LF ja no elimina la etiqueta canònica del nucli de WordPress i ja no suprimeix la sortida hreflang del plugin SEO.','Disabled'=>'Desactivat','Disabled (by setting)'=>'Desactivat (per configuració)','Disabled (mode setting)'=>'Desactivat (per mode)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Desactivat perquè el plugin social-share mu ja proporciona aquesta funció.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS està configurat.','Display'=>'Mostra','Displays the Lingua Forge language switcher.'=>'Mostra el commutador de llengua de Lingua Forge.','Do not output any OG tags.'=>'No emetis cap etiqueta OG.','Documentation'=>'Documentació','Done'=>'Fet','Done — {done} of {total} post(s) fixed.'=>'Fet — {done} de {total} publicació(s) arreglada(s).','Down'=>'Baix','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Descarrega i instal·la un paquet de llengua del nucli de WordPress directament des de WordPress.org. Un cop instal·lat, la configuració regional està disponible per a la rutes URL i el flux de treball de traducció AI. La llista de llengües disponibles es recupera a demanda — fes clic al botó de sota per carregar-la.','Dropdown direction'=>'Direcció del desplegable','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Cada mètrica dóna un dels quatre estats: ok (ple pes), warn (50 % del pes), fail (0), o info (0, sense penalització). Una puntuació ≥ 80 és verd, 50–79 àmbar, per sota de 50 vermell.','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Cada publicació es valora de 0 a 100 segons sis mètriques basades en regles: títol, meta descripció, comptador de paraules, estructura d’encabezaments, cobertura de text alternatiu d’imatges, i enllaços interns. Es donen sempre deu punts per al temps de lectura (només informatiu). Els 90 punts restants es distribueixen entre les altres mètriques amb pesos que varien segons el perfil de contingut (veure a baix).','edit'=>'editar','Editors and above (edit_others_posts)'=>'Editors i més (edit_others_posts)','Enable API response caching'=>'Activa la memòria cau de respostes de l\'API','Enable block-level translation cache reuse across posts'=>'Activa la reutilització de la memòria cau de traducció a nivell de bloc entre publicacions','Enable Social Share URL rewriting for Social Icons blocks'=>'Activa la reescriptura de URL de Social Share per a blocs d\'icones socials','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Activa quan el teu tema mostra el títol de la publicació com a H2 en lloc d\'un H1 (comú en alguns temes de blocs). L\'anàlisi obté la pàgina renderitzada i, si no troba un H1 però troba un H2, promociona el primer H2 a H1 per a la puntuació.','Environment'=>'Entorn','environment variable'=>'variable d\'entorn','Error'=>'Error','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Cada vegada que s’analitza una publicació, la puntuació s’emmagatzema a la metadada de la publicació. La columna de llengua de la llista de publicacions mostra una insígnia de "SEO N" codificada per colors per a qualsevol publicació que s’hagi analitzat almenys una vegada. Quan s’emmagatzemen dues puntuacions, un indicador de delta (↑N / ↓N) mostra el canvi des de l’última execució.','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Exactament un H1 és necessari. El H1 normalment és el títol de la publicació renderitzat pel tema — s’obté de la pàgina renderitzada en viu quan és possible, i del contingut de la publicació com a reserva.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Exemple de configuració compatible: idioma del lloc WP = CA (català), idiomes de contingut = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Exemple de configuració no compatible: idioma del lloc WP = EN (anglès), idiomes de contingut = CA + ES només. L\'anglès no és una llengua de contingut, per tant Lingua Forge no pot assignar el locale de WP a cap grup de traducció.','Exclude from navigation menus'=>'Exclou dels menús de navegació','Exclude from routing'=>'Excloure del ruteig','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Excloure aquest tipus de publicació del ruteig per idioma — les seves publicacions ja no apareixeran aquí ni rebran _lf_lang. Això no es pot desfer automàticament.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Excloure aquest tipus de publicació del ruteig per idioma? Les seves publicacions ja no apareixeran en aquesta llista ni rebran _lf_lang. Pots revertir això a Configuració → Enrutador → Exclusió de filtres de consulta.','excluded from routing'=>'exclòs del ruteig','Excluded post types'=>'Tipus de publicació exclosos','Excluding…'=>'Excloent…','Expand'=>'Amplia','Expected: {expected}'=>'Esperat: {expected}','External share services'=>'Serveis d\'intercanvi externs','Extra guidance — tone, style, constraints, target audience…'=>'Orientació extra — to, estil, restriccions, públic objectiu…','Extra guidance — tone, style, constraints…'=>'Orientació extra — to, estil, restriccions…','Failed to save exclusion.'=>'Error en desar l’exclusió.','Failed. Please try again.'=>'Error. Torna-ho a provar.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL de la imatge de reserva utilitzada quan una pàgina no té imatge destacada, logotip del lloc o icona del lloc. Es mostra en les previsualitzacions socials per arxius, l\'índex del blog i qualsevol pàgina singular sense miniatura.','Feature'=>'Funció','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Les funcions es agrupen en dues categories. Introdueix l\'identificador exacte del model per a cada categoria i proveïdor. Deixa un camp en blanc per utilitzar el valor predeterminat integrat (mostrat com a marcador de posició). Només es criden els models del proveïdor actiu en temps d\'execució — configura els altres prèviament si planejes canviar.','File copied to safe storage successfully.'=>'Arxiu copiat a l\'emmagatzematge segur amb èxit.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Les modificacions d\'arxius estan deshabilitades (DISALLOW_FILE_MODS).','Files'=>'Arxius','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Els arxius es guarden al directori següent. Útil per diagnosticar problemes de traducció — desactiva-ho quan tinguis el que necessites perquè els arxius no s\'acumulin. També pots forçar-ho des de wp-config.php amb `define( \'LINGUAFORGE_AI_DEBUG\', true );` que substitueix l\'interruptor.','Filter'=>'Filtre','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtra per idioma i tipus de publicació, navega pel teu contingut i fes clic a Analitza en qualsevol element per executar una auditoria SEO basada en regles — longitud del títol, descripció meta, comptador de paraules, estructura de títols, cobertura de text alternatiu d\'imatge i enllaços interns.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra amb linguaforge_debug_dir per redirigir la sortida de depuració a una ubicació no pública.','Finding'=>'Cercant','Fix'=>'Corregir','Fix All'=>'Corregir tot','Fix all links'=>'Corregir tots els enllaços','Fix all parts'=>'Corregir totes les parts','Fix Links'=>'Corregir enllaços','Fix Nav'=>'Corregir navegació','Fix Parts'=>'Corregir parts','Fix Template'=>'Corregir plantilla','Fix: go to'=>'Corregir: anar a','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Corregeix l\'espai de noms de l\'Editor del lloc i la etiqueta _lf_lang en totes les plantilles FSE generades per LF emmagatzemades a la base de dades. Executa-ho una vegada després d\'actualitzar des d\'una versió anterior de Lingua Forge — mou les plantilles derivades de WooCommerce del grup de temes actiu al grup de WooCommerce a l\'Editor del lloc, i assegura que totes les plantilles generades siguin detectables pels informes de cobertura.','Fixing {n} / {total}…'=>'Corregint {n} / {total}…','Fixing…'=>'Corregint…','Flush Permalink Rules'=>'Buida les regles de permalinks','Flush Permalinks'=>'Buida permalinks','Flush Sitemap Cache'=>'Buida la memòria cau del mapa del lloc','Footnote Content'=>'Contingut de la nota a peu','footnote(s) translated — applied together with content.'=>'nota(s) traduïda — aplicada juntament amb el contingut.','Footnotes'=>'Notes a peu','Footnotes payload (advanced)'=>'Càrrega útil de notes a peu (avançat)','Forbidden'=>'Prohibit','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçat a OFF per la constant LINGUAFORGE_AI_DEBUG a wp-config.php. Elimina aquesta línia per controlar aquest commutador des d\'aquí.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçat a ON per la constant LINGUAFORGE_AI_DEBUG a wp-config.php. Elimina aquesta línia per controlar aquest commutador des d\'aquí.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Força la regeneració del mapa del lloc en la propera sol·licitud. Utilitza-ho després d\'importacions massives o edicions manuals de relacions de traducció.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Has trobat un error o comportament inesperat? Obre un problema a GitHub — inclou el bloc d\'Informació de Depuració d\'aquesta pàgina i una breu descripció del que esperaves vs. el que va passar.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'S\'han trobat {parts} en <strong>{total}</strong> de <strong>{scanned}</strong> publicacions escanejades per <strong>{lang}</strong>.','From'=>'De','Front Page'=>'Pàgina principal','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Localització FSE: esbossar, traduir i corregir enllaços a les plantilles i parts de plantilles de l\'Edició Completa del lloc directament des d\'aquesta pestanya.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Plantilles FSE sembrades des de l\'actual tema. Crea i personalitza al Editor del lloc.','Full'=>'Completa','Full Article'=>'Article complet','Full post'=>'Publicació completa','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Traducció de pàgina completa, Generador de contingut (els models de gamma mitjana són completament suficients)','General'=>'General','Generate'=>'Genera','Generate Content'=>'Genera contingut','Generate content…'=>'Genera contingut…','Generate Excerpt'=>'Genera extracte','Generate Meta Description'=>'Genera descripció meta','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Genera el mapa del lloc multilingüe a /lf-sitemap.xml','Generated Content'=>'Contingut generat','Generated meta description'=>'Meta descripció generada','Generating…'=>'Generant…','Generation failed.'=>'La generació ha fallat.','Getting started'=>'Començar','Global AI preset'=>'Preestablert d\'IA global','Global default (%s)'=>'Per defecte global (%s)','Glossary'=>'Glosari','Glossary entry added.'=>'Entrada de glosari afegida.','Glossary entry removed.'=>'Entrada de glosari eliminada.','Glossary Tab'=>'Pestanya de glosari','Google (Gemini)'=>'Google (Gemini)','Google AI Studio'=>'Estudi de Google AI','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Mode H2-com-H1 activat — el títol compta com a H1 equivalent. (Les etiquetes d\'encapçalament no es podrien detectar a partir de la pàgina renderitzada; verifiqueu que el vostre tema mostra correctament el títol.)','Heading structure rules'=>'Regles d’estructura d’encabezaments','Headings'=>'Encapçalaments','Hide'=>'Amaga','High-Performance Order Storage (HPOS)'=>'Emmagatzematge d’ordres d’alt rendiment (HPOS)','Hints'=>'Pistes','Home link text'=>'Text del enllaç d\'inici','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Com hauria d\'aparèixer a la traducció. Escriu el mateix valor que el terme original per instruir la IA a conservar-lo literalment.','How to use'=>'Com utilitzar','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT sincronitzat — transitori; els filtres de metadades LF s’apliquen a la còpia de CPT.','Hreflang'=>'Hreflang','Hreflang output'=>'Sortida Hreflang','Hreflang settings saved.'=>'Configuracions de hreflang desades.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Icona + etiqueta','Icon only'=>'Només icona','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Si està seleccionat, desinstal·lar el plugin eliminarà permanentment totes les assignacions de llengua, relacions de traducció, metadescripcions, preestabliments per pàgina, el glosari d\'IA i la Memòria de Traducció per a cada publicació d\'aquest lloc. Això no es pot desfer. Deixa-ho sense seleccionar a menys que estiguis eliminant completament el suport multilingüe del lloc.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Si tens un plugin SEO general instal·lat, aquest panell mostra com LF s\'adapta per evitar sortida duplicada. L\'objectiu és evitar col·lisions — no cooperació. LF sempre proporciona la capa SEO multilingüe (hreflang, og:locale, esquema inLanguage) que requereix coneixement de la configuració de rutes de LF per produir correctament.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Si tens instal·lat Yoast SEO, Rank Math, All in One SEO o SEOPress, Lingua Forge els detecta i s\'adapta per evitar sortida duplicada. Per hreflang, LF s\'encarrega completament i suprimeix la sortida del plugin perquè aquests plugins no poden produir hreflang correcte per a una configuració de rutes multilingüe. Per Open Graph, LF afegeix només og:locale i og:locale:alternate — els senyals multilingües que el plugin no pot proporcionar — i deixa el conjunt base OG al plugin. Per Schema.org, LF desactiva completament la seva pròpia sortida per evitar conflictes en els gràfics JSON-LD.','Images'=>'Imatges','Improve writing'=>'Millora l\'escriptura','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'A l\'editor de blocs, afegeix un bloc d\'Icones Socials. Per a cada icona, obre la configuració de l\'enllaç i introdueix un dels valors "share:" a continuació com a URL. A la part frontal, LF el substitueix pel URL de compartició correcte per a la pàgina actual.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Inclou nom, descripció, inLanguage, url, imatge, i una Oferta amb preu, monedaPreu, i disponibilitat. El preu i la disponibilitat provenen del producte de l\'idioma original (model d\'estoc compartit).','Includes site name, url, and inLanguage.'=>'Inclou nom del lloc, url, i inLanguage.','Informative'=>'Informatiu','Input tokens'=>'Tokens d\'entrada','Install'=>'Instal·la','Install a Language'=>'Instal·la un idioma','Installed SEO plugins'=>'Plugins SEO instal·lats','Installing…'=>'S\'està instal·lant…','instock / oos / pending from WC stock status'=>'en stock / oos / pendent des de l\'estat de stock de WC','Instructions (optional)'=>'Instruccions (opcional)','Instructions / key points'=>'Instruccions / punts clau','Insufficient permissions.'=>'Permisos insuficients.','Integration API'=>'API d\'integració','Internal Link Fixer'=>'Corrector d\'enllaços interns','Introduction only'=>'Només introducció','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Clau API no vàlida — revisa la clau introduïda a la configuració del proveïdor d’AI.','Invalid file reference.'=>'Referència de fitxer no vàlida.','Invalid filename.'=>'Nom de fitxer no vàlid.','Invalid language code.'=>'Codi de llengua no vàlid.','Invalid language.'=>'Llengua no vàlida.','Invalid locale code.'=>'Codi de localització no vàlid.','Invalid or primary language.'=>'Llengua no vàlida o principal.','Invalid post ID.'=>'ID de publicació no vàlid.','Invalid post type.'=>'Tipus de publicació no vàlid.','Invalid taxonomy.'=>'Taxonomia no vàlida.','Invalid template part.'=>'Part de plantilla no vàlida.','Invalid template type.'=>'Tipus de plantilla no vàlid.','JavaScript-powered actions'=>'Accions amb JavaScript','Just now'=>'Just ara','Key points, ideas, or structure to build from…'=>'Punts clau, idees o estructura per construir...','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Les claus estan xifrades en repòs utilitzant AES-256-GCM amb un secret específic del lloc (LINGUAFORGE_SECRET). No comparteixis exportacions de bases de dades sense rotar primer el secret.','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Les claus estan xifrades amb AES-256-CBC abans de ser emmagatzemades a la base de dades de WordPress. El secret de xifrat és derivat dels salts d\'autenticació de WordPress (wp-config.php), de manera que les claus en text pla mai no toquen la base de dades.','Landing / Short-form'=>'Pàgina d\'aterratge / Forma curta','Language'=>'Llengua','Language %s installed successfully.'=>'Llengua %s instal·lada amb èxit.','Language (optional)'=>'Llengua (opcional)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'La instal·lació de llengües està desactivada en aquest servidor (DISALLOW_FILE_MODS està configurat).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'La instal·lació de llengües està desactivada en aquest servidor. La constant DISALLOW_FILE_MODS està configurada a wp-config.php. Instal·la paquets de llengües manualment via WP-CLI: wp language core install de_DE','Language label'=>'Etiqueta de llengua','Language Overrides'=>'Anotacions de llengua','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Anotacions de llengua: gestiona arxius personalitzats .po/.mo per a les cadenes de la interfície d\'usuari de Lingua Forge. Utilitza això en lloc d\'editar directament els arxius del plugin — les anotacions sobreviuen a les actualitzacions.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'La instal·lació del paquet de llengua ha fallat. La llengua ja pot estar instal·lada, el codi de localització pot ser incorrecte, o el servidor pot bloquejar l\'escriptura d\'arxius.','Language Setup'=>'Configuració de llengua','Language Switcher'=>'Selector de llengua','Language switcher'=>'Selector de llengua','Language uninstalled. %d post deleted.'=>'Llengua desinstal·lada. %d publicació eliminada.' . "\0" . 'Llengua desinstal·lada. %d publicacions eliminades.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Còpies específiques de llengua de les parts de plantilla del tema. Un cop estructurades, les plantilles s\'actualitzen per fer referència a la part específica de la llengua.','Language:'=>'Llengua:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Llengües actualment conegudes pel router (derivades dels paquets de localització de WordPress instal·lats més la llengua principal). Instal·la paquets de llengües addicionals a la secció inferior per fer més llengües disponibles per a la rutes i la traducció.','Last 30 days'=>'Últims 30 dies','Last 7 days'=>'Últims 7 dies','Last generated: %s'=>'Darrera generació: %s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Últim resultat SEO basat en regles. Executa l\'anàlisi a Configuració → SEO → Anàlisi per actualitzar.','Last run: %s ago'=>'Última execució: fa %s','Lead paragraph (≤60 w)'=>'Paràgraf principal (≤60 paraules)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Deixa en blanc un camp de model per utilitzar el predeterminat integrat per a aquest nivell. El text de marcador de posició mostra quin model s\'utilitzarà.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deixa en blanc per a noms de marca i termes independents de la llengua que s\'haurien d\'aplicar independentment de la llengua de la qual traduïm.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deixa en blanc per aplicar aquesta entrada a totes les llengües objectiu — ideal per a noms de marca, abreviatures i termes que s\'han de preservar textualment en cada traducció.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deixa en blanc per mantenir la clau existent. Introdueix un valor nou per substituir-la.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deixa en blanc per utilitzar el predeterminat integrat. Esborrar una anotació guardada restableix el valor predeterminat en la propera actualització.','Legacy lf-social-share mu-plugin'=>'Plugin mu legat lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Plugin mu legat lf-social-share detectat. LF està ajornant el conjunt OG base al plugin mu i només emet og:locale + og:locale:alternate. Pots desactivar el plugin mu — el Compartir Social integrat de LF (SEO → Pestanya de Compartir Social) i Open Graph cobreixen la mateixa funcionalitat.','Legacy post-based (CPT)'=>'Post antic (CPT)','Legal / Compliance'=>'Legal / Compliment','Legal / Compliance instructions'=>'Instruccions legals / de compliment','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF sempre afegeix og:locale i og:locale:alternate — els senyals OG multilingües que cap plugin SEO general pot produir correctament. Per al conjunt OG base (og:title, og:description, og:image), LF ho emet quan cap altre plugin està present. Quan s\'instal·la un plugin SEO, LF salta el conjunt base per evitar etiquetes duplicades — no perquè el plugin sigui "millor", sinó perquè la duplicació no produeix valor.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF genera el seu propi mapa del lloc amb alternants xhtml:link per a tots els grups de traducció. Quan s\'instal·la un plugin SEO, aquest genera un mapa del lloc separat — ambdós coexisteixen de manera independent. Envia\'ls a Google Search Console: el mapa del lloc del plugin SEO per a la descoberta de contingut, el mapa del lloc de LF per a senyals de relació de llengua.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF està emetent etiquetes hreflang i ha eliminat l\'etiqueta canònica del nucli de WordPress en pàgines multilingües.','LF is suppressing hreflang output from: %s'=>'LF està suprimint l\'output hreflang de: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF emet hreflang precís per a cada llengua configurada, incloent x-default. Els plugins SEO generals no tenen accés a la configuració de rutes de LF i produirien hreflang basat en suposicions d\'URL incorrectes. LF suprimeix la seva sortida mitjançant un filtre per evitar col·lisions.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF emet JSON-LD multilingüe amb anotacions inLanguage vinculades a la seva configuració de rutes de llengua. Quan s\'instal·la un plugin SEO, LF desactiva completament el seu esquema: gràfics JSON-LD duplicats que produeixen errors de validació i no hi ha una manera neta de complementar un gràfic existent.','LF provides'=>'LF proporciona','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF elimina la etiqueta canònica del nucli de WordPress a les pàgines multilingües perquè les regles de reescriptura amb prefix de llengua del router i l\'hreflang x-default són els senyals canònics correctes per a un lloc multilingüe. Això evita una doble canònica si un plugin SEO també en genera una. LF no afegeix la seva pròpia canònica — la ruta de llengua ja fa que cada URL sigui canònica.','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Entrades propietat de LF actualment registrades a $wp_rewrite->extra_rules_top. Útil per diagnosticar 404s o conflictes de rutes. Copia aquestes quan facis un informe de bug.','Light'=>'Llum','Light (default — fast and cost-effective)'=>'Llum (per defecte — ràpid i econòmic)','Light (fast and cost-effective — Haiku / Flash)'=>'Llum (ràpid i econòmic — Haiku / Flash)','Light model'=>'Model lleuger','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Llum: utilitzat per a descripcions meta i generació d\'extractes — ràpid, de baix cost.','Limit results to pages in the given Lingua Forge language code.'=>'Limita els resultats a pàgines amb el codi de llengua Lingua Forge donat.','Limits'=>'Límits','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge afegeix rutes multilingües, traducció amb IA, etiquetes SEO hreflang i un canviador de llengua al teu lloc de WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge afegeix propietats Open Graph específiques de WooCommerce a les pàgines de producte perquè compartir una URL de producte a Facebook, Pinterest i plataformes similars mostri el tipus de producte, preu i disponibilitat correctes.','Lingua Forge AI Tools'=>'Eines d\'IA de Lingua Forge','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge amplia el bloc d\'icones socials del nucli de WordPress amb URLs de compartició dinàmiques. Estableix l\'enllaç de qualsevol icona a un valor "share:" i LF el reescriu a l\'URL de compartició correcte o a l\'acció JavaScript en renderitzar — sense necessitat de codi personalitzat ni plugin de tercers.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge genera un mapa del lloc XML dedicat a /lf-sitemap.xml que afegeix enllaços alternatius de llengua per a tot el contingut traduït. Aquest mapa complementa el mapa del lloc del nucli de WordPress i qualsevol mapa del lloc d\'un plugin SEO — no els substitueix.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge és una solució SEO multilingüe completa. No cal cap plugin SEO addicional.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge és una solució SEO multilingüe completa. No cal cap plugin SEO ni de mapa del lloc addicional.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge genera etiquetes <link rel="alternate" hreflang> per a cada idioma configurat a cada pàgina, incloent x-default que apunta a l\'idioma original. Aquest és el principal senyal SEO multilingüe per a Google i altres motors de cerca — no cal cap plugin SEO addicional.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge genera etiquetes meta Open Graph i Twitter Card perquè les URL compartides mostrin la llengua, títol, descripció i imatge correctes a les plataformes socials.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge genera dades estructurades JSON-LD de Schema.org perquè els motors de cerca entenguin el tipus de contingut, la llengua i els metadades. Aquesta és la manera principal de comunicar anotacions inLanguage per a contingut multilingüe a Google i altres rastrejadors.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge restringeix dues funcions de Gutenberg per defecte per mantenir la coherència del comportament editorial en totes les llengües. Participa aquí quan necessitis totes les capacitats de Gutenberg / FSE.','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge limita les instàncies secundàries de WP_Query (widgets de barra lateral, blocs de plantilla, consultes de plugins) a l’idioma actiu injectant una restricció de metadada _lf_lang. Els tipus de publicació aquí llistats estan exclosos d’aquesta restricció — les seves consultes sempre són sense filtrar.','Lingua Forge Settings'=>'Configuració de Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge utilitza dues capes de cache independents per evitar trucades redundants a l\'API d\'IA. Utilitza les pestanyes a continuació per inspeccionar i gestionar cadascuna.','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge utilitza dues capes de cache independents per reduir les trucades redundants a l\'API d\'IA:','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge utilitza dues categories de models per proveïdor:','Lingua Forge version'=>'Versió de Lingua Forge','Lingua Forge — Quick Translate'=>'Lingua Forge — Traducció ràpida','Lingua Forge — Settings'=>'Lingua Forge — Configuració','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Els mòduls integrats de Compartir Social i Open Graph de Lingua Forge cobreixen tota la funcionalitat que proporciona el plugin mu, a més de suport multilingüe per og:locale. Pots desactivar el plugin mu de manera segura.','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Versions de Lingua Forge, WordPress i PHP; tema actiu; estructura d\'URL; idioma del lloc WP i idioma de contingut principal. Un indicador vermell al costat de l\'idioma del lloc WP indica que no és un dels idiomes de contingut actius — corregeix-ho a Configuració → General abans de res.','Link copied'=>'Enllaç copiat','link(s)'=>'enllaç(s)','Links'=>'Enllaços','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Llista de plugins SEO de tercers actius. Lingua Forge adapta la seva sortida quan aquests estan presents — consulta Configuració → SEO → Compatibilitat per a la desglossament per funció.','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Llista de tipus de publicació que tenen publicacions publicades sense un valor meta _lf_lang. Les publicacions que falten d\'aquesta etiqueta són invisibles per a tots els filtres d\'idioma. Utilitza el botó Reparar per etiquetar-les amb l\'idioma d\'origen, o Excloure per eliminar el tipus de publicació completament del ruteig d\'idioma.','Load available languages'=>'Carrega idiomes disponibles','Load content'=>'Carrega contingut','Loaded from cache.'=>'Carregat des de la memòria cau.','Loading…'=>'Carregant…','Locale only'=>'Només localitat','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Bloquejat — un plugin SEO conflictiu està actiu. Consulta l\'avís anterior.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate emmagatzema les seves traduccions personalitzades a wp-content/languages/loco/ — una ubicació que pot ser esborrada silenciosament per una actualització del nucli de WP, reinstal·lació del plugin, o si Loco Translate mateix és eliminat. Copiar fitxers aquí els mou a la carpeta i18n-overrides de Lingua Forge, que persisteix a través de tots aquests esdeveniments i s\'carrega automàticament en cada sol·licitud.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copiar a emmagatzematge segur','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Capacitat mínima de WordPress per activar funcions d\'IA. Restringir això en llocs amb múltiples autors evita que Contributors o comptes de prova executin trucades d\'IA de pagament. Sobrescriu per funció mitjançant el filtre linguaforge_required_capability.','Maintenance'=>'Manteniment','Maintenance Tab'=>'Pestanya de manteniment','Make casual'=>'Fes-ho de manera informal','Make concise'=>'Fes-ho de manera concisa','Make formal'=>'Fes-ho de manera formal','Manage your account, review usage, or top up credits:'=>'Gestiona el teu compte, revisa l’ús o afegeix crèdits:','Mark citations needed'=>'Marca les citacions que calen','Max context characters'=>'Caràcters màxims de context','Max hints characters'=>'Caràcters màxims d\'orientacions','Max input characters'=>'Caràcters màxims d\'entrada','Max output tokens'=>'Tokens màxims de sortida','Maximum characters accepted from the input field. Default: 8 000.'=>'Caràcters màxims acceptats des del camp d\'entrada. Per defecte: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Caràcters màxims del contingut de la publicació existent passats a l\'IA com a context de llavor. Per defecte: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Caràcters màxims llegits del camp d\'Orientacions. Per defecte: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Nombre màxim de caràcters del contingut de la publicació enviat a l\'IA. 0 significa sense límit — sempre s\'envia el contingut complet (recomanat). Estableix un valor diferent de zero només si el teu proveïdor té una finestra de context estreta. Es mostra una advertència al registre d\'errors de PHP cada vegada que el contingut es retalla.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Nombre màxim de tokens que l\'IA pot produir en una sola resposta de traducció. Si una traducció es talla silenciosament al final, augmenta aquest valor. Per defecte: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Tokens màxims que l\'IA pot produir per execució de generació. Augmenta-ho si s\'estan tallant articles complets. Per defecte: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Tokens màxims que l\'IA pot produir per traducció ràpida. Per defecte: 2.000.','Meta Description'=>'Meta Descripció','Meta description'=>'Meta descripció','Meta Description, Excerpt Generator'=>'Generador de Meta Descripció, Extracte','Meta Description, Excerpt Generator, quick translate'=>'Meta Descripció, Generador d’Excerpts, traducció ràpida','Metric'=>'Mètric','Minimum role'=>'Rol mínim','Missing'=>'Falta','Missing pattern name or language.'=>'Falta el nom del patró o l\'idioma.','Mode'=>'Mode','Model'=>'Model','Model ID'=>'ID del model','Model tier'=>'Nivell de model','Model tiers'=>'Nivells de model','Models'=>'Models','Modified'=>'Modificat','Most recent cached block'=>'Bloc en cache més recent','Most recent cached response'=>'Resposta en cache més recent','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Enrutament multilingüe, SEO multilingüe complet (hreflang, Open Graph, Schema.org, sitemap), i eines de contingut AI per a WordPress. Detecció d\'idioma, enrutament d\'URL, traducció, generació de contingut, i una capa SEO completa — sense necessitat d\'un plugin complementari.','Multilingual SEO'=>'SEO multilingüe','Multilingual SEO overview'=>'Visió general de SEO multilingüe','My Account'=>'El meu compte','Name'=>'Nom','Name displayed in this language. Leave empty to use the source name.'=>'Nom mostrat en aquest idioma. Deixa-ho buit per utilitzar el nom original.','Navigation'=>'Navegació','Navigation has no content to translate.'=>'La navegació no té contingut per traduir.','Navigation not found.'=>'Navegació no trobada.','Navigation posts are translated via the Router tab, not this button.'=>'Les publicacions de navegació es tradueixen a través de la pestanya Router, no d\'aquest botó.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traducció de navegació requereix un proveïdor d\'IA actiu. Configura una clau API a la pestanya Claves API.','Navigations'=>'Navegacions','Network error — could not reach the provider: %s'=>'Error de xarxa — no s’ha pogut contactar amb el proveïdor: %s','Network error — could not reach the WordPress AJAX endpoint.'=>'Error de xarxa — no s\'ha pogut accedir a l\'endpoint AJAX de WordPress.','Network error.'=>'Error de xarxa.','Never run'=>'Mai correr','No %s version found in this translation group.'=>'No s\'ha trobat cap versió %s en aquest grup de traduccions.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'No cal cap acció. Google va descontinuar el seu endpoint de ping del sitemap a gener 2024 i ara descobreix els sitemaps exclusivament a través de la directiva Sitemap del robots.txt — que LF ja ha configurat. Google ho detectarà en la seva propera exploració.','No active plugins detected.'=>'No s’han detectat plugins actius.','No AI provider configured.'=>'No s\'ha configurat cap proveïdor d\'IA.','No AI provider configured. Add an API key in Settings → API Keys.'=>'No s\'ha configurat cap proveïdor d\'IA. Afegeix una clau API a Configuració → Claves API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'No s\'ha registrat cap ús d\'IA en la finestra seleccionada (%s). Tria un rang més ampli a sobre.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Encara no s\'ha registrat cap ús d\'IA. Un cop un editor executa una traducció, genera una meta descripció, o utilitza qualsevol altra funció d\'IA, els totals apareixeran aquí.','No API key configured for this provider.'=>'No s\'ha configurat cap clau API per a aquest proveïdor.','No API key configured — enter your key in the AI Provider settings.'=>'No s’ha configurat cap clau API — introdueix la teva clau a la configuració del proveïdor d’AI.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Sense instruccions incorporades — cada funció d\'IA utilitza els seus propis valors per defecte ajustats. Omple el camp d\'instruccions personalitzades a continuació per afegir les teves pròpies regles globals del lloc.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'No s\'han detectat plugins SEO conflictius. Lingua Forge gestiona tota la sortida SEO de manera independent.','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'No queden crèdits — afegeix crèdits al teu compte d’OpenAI a platform.openai.com/account/billing.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Encara no s\'han trobat fitxers Loco Translate personalitzats. Apareixen aquí un cop guardes una traducció a Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'No s\'ha detectat cap plugin OG extern. LF està generant el conjunt complet d\'OG + Targeta Twitter.','No file was selected.'=>'No s\'ha seleccionat cap fitxer.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'No hi ha entrades de glossari que coincideixin amb el filtre actual. Esborra el filtre per veure totes les entrades, o afegeix-ne una de nova a continuació.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Encara no hi ha entrades de glossari. Afegeix-ne una a continuació per començar a aplicar la terminologia en les traduccions.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'No s\'ha trobat cap H1. Normalment, el títol de la publicació és l\'H1 — verifica que el teu tema el mostra.','No images found in content.'=>'No s\'han trobat imatges en el contingut.','No internal links found to update.'=>'No s\'han trobat enllaços interns per actualitzar.','No key'=>'Sense clau','No language-specific template parts found to map.'=>'No s\'han trobat parts de plantilla específiques d\'idioma per mapar.','No LF meta description set — using excerpt/content.'=>'No s\'ha configurat cap meta descripció LF — s\'utilitza l\'extracte/contenu.','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'No s\'han trobat regles de reescriptura LF. Actualitza els enllaços permanents si això no era esperat.','No links found.'=>'No s\'han trobat enllaços.','No links found. Internal links improve crawlability and user navigation.'=>'No s\'han trobat enllaços. Els enllaços interns milloren la rastreabilitat i la navegació de l\'usuari.','No meta description found. Generate one via the AI meta description feature.'=>'No s\'ha trobat cap meta descripció. Genera\'n una mitjançant la funció de meta descripció d\'IA.','No navigation references needed updating.'=>'No cal actualitzar cap referència de navegació.','No override files uploaded yet.'=>'Encara no s\'han carregat arxius de substitució.','No PHP limit'=>'Sense límit de PHP','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'No s\'ha trobat cap arxiu robots.txt físic. WordPress el genera virtualment i la directiva del mapa del lloc de LF s\'inclou automàticament.','No published posts found for the selected filters.'=>'No s\'han trobat publicacions publicades pels filtres seleccionats.','No response from AI provider. Check your API key and try again.'=>'No hi ha resposta del proveïdor d\'IA. Comproveu la vostra clau API i torneu-ho a provar.','No response from provider — check the error log for details.'=>'No hi ha resposta del proveïdor — comproveu el registre d\'errors per a més detalls.','No secondary languages configured.'=>'No hi ha cap idioma secundari configurat.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'No hi ha idiomes secundaris configurats. Instal·leu un paquet d\'idioma a dalt per habilitar l\'esquelet de la plantilla.','No source content found to translate.'=>'No s\'ha trobat contingut font per traduir.','No source page linked yet.'=>'Encara no hi ha cap pàgina enllaçada com a font.','No template part references needed updating.'=>'No cal actualitzar cap referència a la part de la plantilla.','No terms found.'=>'No s\'han trobat termes.','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'No s\'ha detectat cap plugin SEO de tercers. Lingua Forge gestiona tota la sortida SEO multilingüe.','No title set.'=>'No s\'ha establert cap títol.','No translated content found. The sitemap will populate once posts have been translated.'=>'No s\'ha trobat contingut traduït. El mapa del lloc s\'omplirà un cop s\'hagin traduït les publicacions.','No translation found — analyzed the source language version.'=>'No s\'ha trobat cap traducció — s\'ha analitzat la versió en llengua font.','No {lang} translation registered (TRID missing)'=>'No hi ha cap traducció de {lang} registrada (TRID missing)','No — WooCommerce integration class not loaded'=>'No — La classe d\'integració de WooCommerce no carregada','not a content language — see notice above'=>'no és una llengua de contingut — vegeu l\'avís anterior','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Encara no s\'ha generat. El mapa del lloc es construeix en la primera visita a l\'URL del mapa del lloc i s\'emmagatzema en memòria cau durant 24 hores.','Notes'=>'Notes','Nothing — all types disabled'=>'Res — tots els tipus estan desactivats','Notice message'=>'Missatge de notificació','Notice settings'=>'Configuració de notificacions','Notify search engines'=>'Notifica als motors de cerca','Numeric permalink structure is not supported.'=>'La estructura d\'enllaç permanent numèrica no és compatible.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Etiquetes OG/Twitter Card: gestionades pel mòdul Open Graph de LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Bloc en memòria cau més antic','Oldest cached response'=>'Resposta en memòria cau més antiga','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Còpia d\'un resum del sistema en text pla que cobreix totes les seccions anteriors. Enganxa-ho en un problema de GitHub o sol·licitud de suport perquè l\'entorn complet sigui visible d\'un cop d\'ull.','Only .mo files are accepted.'=>'Només s\'accepten arxius .mo.','Open an issue →'=>'Obre un problema →','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph i Targetes de Twitter','Open Graph output'=>'Sortida Open Graph','Open Graph settings saved.'=>'Configuració d\'Open Graph desada.','Open Search Console →'=>'Obre la Consola de cerca →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Obre la safata de compartició web nativa del navegador (iOS, Android, alguns escriptoris). Torna a copiar al porta-retalls si no és compatible.','OpenAI (GPT)'=>'OpenAI (GPT)','OpenAI Platform'=>'Plataforma OpenAI','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Context opcional per als editors (p. ex. "ASIC = Circuit Integrat Específic per a Aplicacions; conservar en anglès en contexts tècnics").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opcional. Bing ja llegeix la directiva Sitemap: des de robots.txt — això només desencadena una nova rastrejada immediata en lloc d\'esperar la propera revisió programada.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opcional. Yandex ja llegeix la directiva Sitemap: des de robots.txt — això només desencadena una nova rastrejada immediata en lloc d\'esperar la propera revisió programada.','Order storage'=>'Emmagatzematge d’ordres','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Ordres a wp_posts — assegureu-vos que shop_order estigui exclòs de la rutes LF.','Output'=>'Sortida','Output Article or WebPage schema on singular posts and pages'=>'Sortida de l\'esquema Article o WebPage en publicacions i pàgines singulars','Output hreflang tags in wp_head'=>'Sortida de les etiquetes hreflang a wp_head','Output mode'=>'Mode de sortida','Output Open Graph tags in wp_head'=>'Sortida d\'etiquetes Open Graph a wp_head','Output Product schema on WooCommerce product pages'=>'Sortida de l\'esquema Producte a les pàgines de producte de WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Sortida de JSON-LD de Schema.org a wp_head','Output tokens'=>'Tokens de sortida','Output WebSite schema on the front page and blog index'=>'Sortida de l\'esquema WebSite a la pàgina principal i a l\'índex del blog','Overall SEO score'=>'Puntuació global de SEO','overridden'=>'sobre-escrit','Override file deleted.'=>'Arxiu de substitució eliminat.','Override file uploaded successfully.'=>'Arxiu de substitució carregat amb èxit.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobrescriu la preset d\'IA per a Traducció i Generació de contingut en aquesta pàgina. Totes les altres funcions sempre utilitzen la preset global.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobrescriu la preset d\'IA per a Traducció i Generació de contingut en aquesta pàgina. Les instruccions personalitzades a nivell de lloc (Configuració → Comportament) sempre s\'afegeixen a cada sol·licitud independentment d\'aquesta selecció.','Overview'=>'Visió general','Page'=>'Pàgina','Part'=>'Part','Paste a footnote, sentence, or any snippet here…'=>'Enganxa una nota al peu de pàgina, una frase o qualsevol fragment aquí…','Paste text, or select text in the editor first…'=>'Enganxa text, o selecciona primer el text a l\'editor…','Paste text, or select text on the page first…'=>'Enganxa text, o selecciona primer el text a la pàgina…','Paste your API key…'=>'Enganxa la teva clau API…','Path prefix (/de/)'=>'Prefix de camí (/de/)','Path prefix — example.com/de/'=>'Prefix del camí — example.com/de/','Path routing requires a post-name based permalink structure. Change it in'=>'El ruteig de camí requereix una estructura d\'enllaç permanent basada en el nom de la publicació. Canvia-ho a','Pattern'=>'Patró','Pattern has no content to translate.'=>'El patró no té contingut per traduir.','Pattern not found.'=>'Patró no trobat.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patró traduït i desat. Copia el contingut al teu post CPT mitjançant el inserter de patrons de l\'editor de blocs o utilitza\'l com a punt de partida per a un bloc reutilitzable.','Pattern translation failed.'=>'La traducció del patró ha fallat.','Payment required — your account has no remaining credits.'=>'Pagament necessari — el vostre compte no té crèdits restants.','Per-Post Analysis'=>'Anàlisi per publicació','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Càlcul en memòria cau per a traduccions generades per IA, metadescripcions, extractes i contingut. Les entrades s\'invaliden automàticament quan canvia el contingut o el proveïdor/model d\'IA.','Permalink rules flushed successfully.'=>'Les regles de permalink s\'han buidat amb èxit.','Permalink Structure'=>'Estructura d\'enllaç permanent','Permalink structure is compatible with Lingua Forge path routing.'=>'L\'estructura d\'enllaç permanent és compatible amb el ruteig de camí de Lingua Forge.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Elimina permanentment totes les plantilles, parts de plantilla, patrons, menús de navegació, publicacions, pàgines, tipus de publicació personalitzats, productes i variacions de producte associats amb aquest idioma. També elimina els fitxers del paquet de localització de WordPress perquè aquest idioma ja no aparegui al router. Aquesta acció no es pot desfer.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Desinstal·la permanentment %s? Això eliminarà tot el contingut traduït per a aquest idioma i no es pot desfer.','Permission denied.'=>'Permís denegat.','Persuasive'=>'Persuasiu','PHP constant'=>'Constant de PHP','PHP max_execution_time'=>'Temps màxim d\'execució de PHP','PHP memory_limit'=>'Límit de memòria de PHP','PHP version'=>'Versió de PHP','Pin on Pinterest'=>'Fes un pin a Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Terms de pin que no s\'han de traduir o que sempre s\'han de representar d\'una manera específica (per exemple, noms de marca, noms de producte, acrònims). Les restriccions del glossari s\'injecten a cada sol·licitud de traducció d\'IA per a totes les funcions: traducció de publicacions, metadescripció, extracte i traducció de plantilles FSE.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Llenguatge senzill','Plain permalinks are not supported.'=>'Els enllaços permanents plans no són compatibles.','Please enter some instructions first…'=>'Introdueix primer algunes instruccions…','Please enter some text first…'=>'Introdueix primer algun text…','Plugin'=>'Plugin','Post'=>'Publicació','Post not found or not published.'=>'Publicació no trobada o no publicada.','Post not found.'=>'Publicació no trobada.','Post on X / Twitter'=>'Publica a X / Twitter','Post type'=>'Tipus de publicació','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Els slugs de tipus de publicació separats per comes o línies noves. Els canvis tenen efecte immediatament en desar — no cal actualitzar els enllaços permanents.','Post Types'=>'Tipus de publicació','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Les publicacions sense _lf_lang són invisibles per a cada filtre de llengua de Lingua Forge. Això pot passar quan el contingut s\'importa o es crea abans d\'activat el plugin.','Prefilled from excerpt. Edit to override.'=>'Precomplert a partir de l\'extracte. Edita per sobreescriure.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Preu i disponibilitat sempre reflecteixen el producte de la llengua d\'origen (model d\'estoc compartit). Les etiquetes només s\'emeten quan el mòdul Open Graph de LF està configurat a "Completa" o "Automàtica" sense cap plugin SEO conflictiu detectat.','Primary content language'=>'Llengua principal del contingut','Primary Language'=>'Llengua principal','Primary language'=>'Llengua principal','Primary language saved.'=>'Llengua principal desada.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Llengua principal: la llengua en què està escrit el teu contingut existent. Totes les traduccions es produeixen a partir d\'aquesta llengua; canviar-la no mou ni elimina cap publicació.','Processing…'=>'Processant…','Product'=>'Producte','Product / eCommerce'=>'Producte / comerç electrònic','Product Open Graph'=>'Open Graph del producte','Product — WooCommerce product pages'=>'Producte — pàgines de producte de WooCommerce','Profile'=>'Perfil','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Els perfils adapten els llindars i els pesos al tipus de contingut que s\'analitza. El perfil es resol automàticament; podeu sobrescriure\'l per a cada execució d\'anàlisi des del menú desplegable de perfils.','Provider'=>'Proveïdor','Provider error (HTTP %1$d): %2$s'=>'Error del proveïdor (HTTP %1$d): %2$s','Provider returned no response. Check the WordPress error log for details.'=>'El proveïdor no va retornar cap resposta. Comproveu el registre d\'errors de WordPress per a més detalls.','Provider service temporarily unavailable — try again in a moment.'=>'Servei del proveïdor temporalment no disponible — torneu-ho a provar en un moment.','Quality'=>'Qualitat','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualitat (per defecte — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualitat (Sonnet / GPT-4o / Gemini Pro)','Quality model'=>'Model de qualitat','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Qualitat: utilitzat per a la traducció de publicacions i generació de contingut — qualitat superior, cost superior.','Query Filter Exclusions'=>'Exclusions de filtres de consulta','Quick Translate'=>'Traducció ràpida','Quick Translation'=>'Traducció ràpida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La Traducció Ràpida s\'utilitza en mode fragment / tros — passatges curts traduïts a demanda des de la barra d\'eines, l\'editor o els popovers de bloc. Utilitza una configuració separada i més lleugera de la traducció de pàgina completa per mantenir les respostes ràpides i econòmiques.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Limitat per taxa — massa sol·licituds enviades al proveïdor; espereu un moment i torneu-ho a provar.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Habilita de nou canLockBlocks de Gutenberg. Útil per a plantilles editorials que necessiten evitar que els col·laboradors moguin o eliminin blocs específics.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Habilita de nou supportsTemplateMode. Fonamental per als fluxos de treball de Edició Completa del lloc on les sobrescripcions de plantilles a nivell de publicació són intencionades.','Re-generates and updates the cached result.'=>'Regenere i actualitza el resultat en caché.','Re-scan'=>'Re-escanejar','Re-scanning…'=>'Re-escanejant…','Re-translate'=>'Re-traduir','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Diagnòstics de només lectura per a la instal·lació actual. No s\'hi canvien configuracions — utilitza-ho per verificar la configuració, detectar problemes i recopilar informació per a informes d\'errors.','Reading time'=>'Temps de lectura','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirigeix els visitants a la seva llengua preferida segons l\'encapçalament Accept-Language del navegador','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Refina encara més — per exemple, "fes-lo més curt" o "usa un to formal"…','Refine further:'=>'Refina encara més:','Refinement'=>'Refinament','Refinement failed — please try again.'=>'El refinament ha fallat — si us plau, torna-ho a provar.','Refining…'=>'Refinant…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenere les regles de reescriptura de WordPress perquè els prefixos d\'URL, els slugs específics de l\'idioma i les reescriptures d\'arxiu estiguin sincronitzats. Necessari després de canviar l\'idioma principal o afegir suport per a un nou idioma.','Remove stored key'=>'Eliminar clau emmagatzemada','Repair failed.'=>'La reparació ha fallat.','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Repareu les etiquetes de cada publicació enrutable que apareix a dalt amb _lf_lang = %s. Les publicacions en tipus de publicació exclosos de rutes no es toquen. Executar això només després d\'importar contingut o en l\'activació inicial — no utilitzeu com a eina massiva de reassignació de llengües.','Repair Template Metadata'=>'Reparar metadades de la plantilla','Repair template metadata'=>'Reparar metadades de la plantilla','Repair — assign _lf_lang = %s to all routable posts above'=>'Reparar — assignar _lf_lang = %s a totes les publicacions enrutables de dalt','Repairing…'=>'Reparant…','Report an issue on GitHub'=>'Informar d\'un problema a GitHub','Request failed — please try again.'=>'La sol·licitud ha fallat — si us plau, torna-ho a provar.','Request failed.'=>'La sol·licitud ha fallat.','Request failed. Check your connection.'=>'La sol·licitud ha fallat. Comprova la teva connexió.','Request failed. Please try again.'=>'La sol·licitud ha fallat. Si us plau, torna-ho a provar.','Requests'=>'Sol·licituds','requests / day'=>'sol·licituds / dia','Reset'=>'Restableix','Result will appear here…'=>'El resultat apareixerà aquí…','Retranslate'=>'Re-traduir','Retranslating…'=>'Re-traducció en curs…','Review carefully — links and slugs not updated.'=>'Revisa atentament — enllaços i slugs no actualitzats.','Review translation before applying'=>'Revisa la traducció abans d\'aplicar-la','Revise'=>'Revisa','Revision'=>'Revisió','Revision Type'=>'Tipus de revisió','Rewrite Rules'=>'Regles de reescriptura','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt actualitzat amb la directiva Sitemap.','Router'=>'Enllaçador','Router Tab'=>'Pestanya de l\'enllaçador','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Executa una auditoria SEO completa en totes les publicacions publicades per a una o totes les llengües actives. Les puntuacions s\'enregistren per publicació i es reflecteixen a les insígnies de la columna de llengua a la llista de publicacions.','Run AI Analysis'=>'Executa l\'anàlisi d\'IA','Save'=>'Desa','Save analysis settings'=>'Desa la configuració d\'anàlisi','Save Debug Setting'=>'Desa la configuració de depuració','Save Hreflang Settings'=>'Desa la configuració de Hreflang','Save Open Graph Settings'=>'Desa la configuració d\'Open Graph','Save Router Settings'=>'Desa la configuració de l\'enllaçador','Save Schema.org Settings'=>'Desa la configuració de Schema.org','Save Settings'=>'Desa la configuració','Save Sitemap Settings'=>'Desa la configuració del mapa del lloc','Save Social Share Settings'=>'Desa la configuració de compartició social','Save the post to persist changes.'=>'Desa la publicació per mantenir els canvis.','Save Uninstall Setting'=>'Desa la configuració de desinstal·lació','Save WooCommerce SEO Settings'=>'Desa la configuració SEO de WooCommerce','Saved to the meta description field when you apply.'=>'Guardat al camp de descripció meta quan s\'aplica.','Scan failed: '=>'Fallada de l\'anàlisi: ','Scan request failed. Please try again.'=>'La sol·licitud de l\'escaneig ha fallat. Torna-ho a provar.','Scanning posts for broken language links…'=>'Escanejant publicacions per enllaços trencats de llengua…','Schema output deferred.'=>'Sortida de l\'esquema ajornada.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Sortida de Schema.org','Schema.org settings saved.'=>'Configuració de Schema.org desada.','Score'=>'Puntuació','Score computation'=>'Càlcul de puntuacions','Score history and badges'=>'Historial de puntuacions i insígnies','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Les puntuacions són una senyal, no un veredicte. Alguns continguts estan limitats estructuralment — pàgines molt curtes, pàgines de destinació amb poc text, o pàgines amb l\'objectiu de navegació més que d\'informació poden obtenir puntuacions més baixes per naturalesa. Utilitza aquesta visió general per detectar veritables mancances de paritat entre llengües, no per perseguir un número.','Search'=>'Cerca','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Console és útil per monitoritzar errors d\'indexació i cobertura, però no és necessari per a la descoberta.','Search Results'=>'Resultats de cerca','Sections'=>'Seccions','Security check failed — file path is not permitted.'=>'Fallada en la comprovació de seguretat — el camí del fitxer no està permès.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Veure Configuració → SEO → Compatibilitat per a la taula completa de comportament per funció.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecciona un idioma per gestionar les seves plantilles FSE, parts de la plantilla i menús de navegació.','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Selecciona una publicació i executa una auditoria SEO detallada per veure els resultats per mètrica i una puntuació per a aquest element específic.','Select language'=>'Selecciona idioma','Send via Telegram'=>'Envia via Telegram','Send via WhatsApp'=>'Envia via WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Anàlisi SEO','SEO character-count info'=>'Informació sobre el comptador de caràcters SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Plugins SEO detectats: %s. LF només mostra og:locale i og:locale:alternate; el plugin detectat gestiona el conjunt complet OG.','SEO Plugins'=>'Plugins SEO','SEO plugins and conflict avoidance:'=>'Plugins SEO i evitació de conflictes:','SEO Score System'=>'Sistema de puntuació SEO','SEO Scores'=>'Puntuacions SEO','SEO Tab'=>'Pestanya SEO','Server setup (subdomain)'=>'Configuració del servidor (subdomini)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Estableix el comportament AI per defecte per a totes les funcions a tot el lloc. Les publicacions individuals poden substituir això per Traducció i Generació de contingut mitjançant la caixa meta Lingua Forge.','Settings'=>'Configuració','Settings saved.'=>'Configuració desada.','Settings → General → Site Language'=>'Configuració → General → Idioma del lloc','Settings → Permalinks'=>'Configuració → Enllaços permanents','Share on Facebook'=>'Comparteix a Facebook','Share on LinkedIn'=>'Comparteix a LinkedIn','Share on Mastodon'=>'Comparteix a Mastodon','Share via email (mailto:)'=>'Comparteix per correu electrònic (mailto:)','Shared / compatibility mode'=>'Mode compartit / de compatibilitat','Shop'=>'Botiga','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'El contingut curt (fins a 3 paràgrafs) mai no es penalitza per la manca de subtítols, independentment del perfil. Una pàgina concisa no es beneficia d\'una estructura de capçalera forçada.','Show home link'=>'Mostra enllaç a l\'inici','Shown when no translation exists for the visitor\'s language.'=>'Mostrat quan no existeix traducció per a l\'idioma del visitant.','Single'=>'Individual','Single %s'=>'Individual %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Títol d\'una sola paraula (%d caràcters) — afegir una segona paraula millora la claredat i la cobertura de paraules clau.','Single: %s'=>'Individual: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Límit global de sol·licituds d\'AI per dia UTC (inclou tant les traduccions de la barra d\'eines com les revisions de blocs). El comptador es reinicia a la mitjanit UTC. Estableix a 0 per desactivar el límit.','Sitemap'=>'Mapa del lloc','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Caché del mapa del lloc buidada. Es regenerarà en la propera visita a l\'URL del mapa del lloc.','Sitemap output'=>'Sortida del mapa del lloc','Sitemap settings saved.'=>'Configuració del mapa del lloc desada.','Sitemap URL'=>'URL del mapa del lloc','Size'=>'Mida','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Compartir bloc d\'icones socials: URLs: gestionat pel Share Social integrat de LF (SEO → Share Social)','Social Share'=>'Compartir Social','Social Share settings saved.'=>'Configuració de Share Social desada.','Some link fixes failed.'=>'Algunes correccions d\'enllaços han fallat.','Some nav ref fixes failed.'=>'Algunes correccions de referències de navegació han fallat.','Some part fixes failed.'=>'Algunes correccions de parts han fallat.','Some parts could not be created.'=>'Algunes parts no es van poder crear.','Some templates could not be created.'=>'Algunes plantilles no es van poder crear.','Some translations failed.'=>'Algunes traduccions han fallat.','source'=>'font','Source file not found.'=>'Fitxer font no trobat.','Source lang'=>'Llengua font','Source language'=>'Llengua de origen','Source term'=>' terme d\'origen','Source title'=>'Títol de la font','Standard'=>'Estàndard','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Els estàndards utilitzen la seva pròpia temperatura ajustada: Traducció T=0.2 (precisa), Traducció ràpida T=0.4, Generador de contingut T=0.6 (creatiu). Els altres preajustaments apliquen una única temperatura fixa a totes les funcions.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Comenceu a escriure en qualsevol camp per veure suggeriments de models, o utilitzeu la taula de referència a sota. Els models de qualitat lleugera i mitjana (Haiku, GPT-4o mini, Gemini Flash) són completament suficients per a la traducció i la generació de contingut — els models flagship "max" augmenten el cost amb un benefici de qualitat mínim per a textos estructurats.','Status'=>'Estat','Status / Actions'=>'Estat / Accions','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Emmagatzema respostes d\'IA en brut indexades per hash de contingut, parella d\'idioma, proveïdor, model i predefinit. Les entrades de la cache s\'invaliden automàticament quan canvia el contingut de la publicació d\'origen. Esborra entrades individuals o tota la cache des d\'aquesta pestanya.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Emmagatzema la sortida completa de la publicació traduïda per hash de contingut. Opt-in (activat a Comportament). Accelerar traduccions repetides de contingut sense canvis. Esborra-ho aquí quan vulguis forçar una passada d\'IA nova independentment de si el contingut ha canviat.','Storytelling'=>'Narració','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Mode de preservació estricta per a contingut legal, regulador, mèdic o tècnic. Quan està activat, cada funció d\'IA utilitza una baixa temperatura d\'assaig i afegeix l\'addenda següent al seu missatge de sistema — la terminologia, els números d\'article, les unitats, els noms de marca i el llenguatge regulador es preserven textualment en lloc de parafrasejar-se.','Structured Outline'=>'Esquema estructurat','Subdomain (de.example.com)'=>'Subdomini (de.exemple.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'El mode de subdomini requereix que el vostre servidor web apunti tots els subdominis de llengua (p. ex. de.exemple.com) a aquesta instal·lació de WordPress. Després de canviar de mode, actualitzeu les regles de permalinks i buideu qualsevol memòria cau. Si la vostra URL d\'inici inclou www (p. ex. www.exemple.com), utilitzeu el filtre lf_base_domain per establir el domini sense subdomini perquè els subdominis es construeixin correctament.','Subdomain — de.example.com/'=>'Subdomini — de.exemple.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Envia aquesta URL a Google Search Console juntament amb el vostre mapa del lloc principal.','Submit to Reddit'=>'Envia a Reddit','Suggested meta description'=>'Meta descripció suggerida','Suggested title'=>'Títol suggerit','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Proveïdors compatibles: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Selecciona el proveïdor actiu del desplegable — només s\'utilitza un proveïdor a la vegada. Introdueix una clau API per a aquest proveïdor per habilitar les funcions d\'IA.','Suppressed: %s.'=>'Sospès: %s.','Switch to a post-name based structure in'=>'Canvia a una estructura basada en el nom de la publicació a','System'=>'Sistema','System Tab'=>'Pestanya del Sistema','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per funció','Tag'=>'Etiqueta','Tags emitted'=>'Etiquetes emeses','Target lang'=>'Llengua de destinació','Target Language'=>'Llengua de destinació','Target language'=>'Llengua de destinació','Target term'=>'Termes de destinació','Target: 140–160 chars for optimal SERP display'=>'Destinació: 140–160 caràcters per a una visualització òptima a SERP','Technical'=>'Tècnic','Technical / Scientific'=>'Tècnic / Científic','Technical / Scientific instructions'=>'Instruccions tècniques / científiques','Template "%s" already exists.'=>'La plantilla "%s" ja existeix.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'La plantilla "{expected}" no existeix — crea-la primer al Editor del lloc.','Template has no content.'=>'La plantilla no té contingut.','Template mode'=>'Mode de plantilla','Template not found or not stored in the database.'=>'Plantilla no trobada o no emmagatzemada a la base de dades.','Template part "%s" already exists.'=>'La part de plantilla "%s" ja existeix.','Template part has no content.'=>'La part de plantilla no té contingut.','Template part not found or not stored in the database.'=>'Part de plantilla no trobada o no emmagatzemada a la base de dades.','Template Parts'=>'Parts de plantilla','Templates'=>'Plantilles','Test connection'=>'Prova de connexió','Testing…'=>'Prova en curs…','Text domain / locale'=>'Àmbit de text / localització','Text to translate'=>'Text a traduir','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'La memòria cau de respostes de l\'API emmagatzema el resultat brut de cada sol·licitud d\'IA — traducció, metadescripció, extracte i generació de contingut — indexat per un hash dels inputs (contingut, parella de llengües, proveïdor, model). Desactiva durant la sintonització de prompts o quan necessites que cada sol·licitud arribi al proveïdor d\'IA. La desactivació no elimina les entrades en memòria cau — tornar a activar-les les restaura.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'La quota diària (configurada a Comportament → Límits) es fa seguiment aquí. Quan s\'aconsegueix la quota, les trucades a l\'IA es suspenen per a la resta del dia. La taula mostra com s\'ha consumit la quota.','The editor did not accept the content — please try again.'=>'L\'editor no va acceptar el contingut — si us plau, torneu-ho a provar.','The following directive is active in your virtual robots.txt:'=>'La directiva següent està activa en el vostre robots.txt virtual:','The lf-social-share mu-plugin is active.'=>'El plugin mu de social sharing lf està actiu.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'El plugin mu lf-social-share està actiu. El Social Share integrat de Lingua Forge està inactiu — el plugin maneja la reescriptura de l\'URL de compartició i les accions JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'El nivell lleuger utilitza el model ràpid configurat a la taula de models anterior (per defecte: Haiku / Flash). Canvia a Qualitat si necessites la mateixa precisió de traducció que el mode de pàgina completa per a fragments.','The phrase as it appears in the source text.'=>'La frase tal com apareix en el text font.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'L\'idioma principal sempre s\'ofereix a la arrel del teu lloc — sense prefix d\'URL en mode de ruta, sense subdomini d\'idioma en mode de subdomini. Tots els altres idiomes utilitzen un prefix de ruta /lang/ (per exemple, example.com/de/) o un subdomini d\'idioma (per exemple, de.example.com), segons la configuració de l\'estructura d\'URL a continuació.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'La pestanya SEO → Compatibilitat mostra l\'estat de detecció en viu i explica exactament què fa LF per cada àrea de funció.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'L\'URL de compartició sempre reflecteix la pàgina actual — no cal introduir manualment l\'URL. El filtre linguaforge_social_share_url et permet substituir l\'URL resolt per a qualsevol servei.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'El mapa del lloc s\'anuncia automàticament en robots.txt. Tots els motors de cerca principals — Google, Bing, Yandex — el descobreixen a partir de robots.txt. No cal enviar-lo manualment.','The source page has no footnotes.'=>'La pàgina font no té notes a peu.','The upload failed — please try again.'=>'La càrrega ha fallat — si us plau, torna-ho a provar.','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'La taula d\'ús mostra el consum de tokens d\'IA desglossat per funció (traducció, meta descripció, extracte, plantilla FSE, anàlisi per lots), proveïdor i model. Utilitza els botons de rang de dates per filtrar per avui, últims 7 dies, últims 30 dies o tot.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'El mapa del lloc del nucli de WordPress llista totes les URLs del teu contingut. El mapa del lloc LF indica als motors de cerca com es relacionen les versions en diferents idiomes mitjançant alternants xhtml:link hreflang. Envia\'ls a Google Search Console per a una cobertura completa.','The WordPress site language (%1$s) is not among the active Lingua Forge content languages (%2$s). This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'L\'idioma del lloc WordPress (%1$s) no està entre els idiomes de contingut actius de Lingua Forge (%2$s). Això fa que les consultes de productes de WooCommerce retornin zero resultats, les imatges dels productes fallin, i totes les consultes de contingut filtrat per idioma es trenquin.','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'L\'idioma del lloc de WordPress (Configuració → General → Idioma del lloc) ha de ser configurat a un dels idiomes que utilitzeu per al contingut — ja sigui l\'idioma principal del contingut o un dels idiomes secundaris. No pot ser un idioma que no tingui contingut al lloc.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Aquestes notes a peu provenen de la pàgina font i es mostren aquí només com a referència. Afegeix-les a aquesta pàgina utilitzant l\'editor de blocs.','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Aquest catàleg s\'actualitza amb cada llançament de Lingua Forge. Provar una connexió a la pestanya de claus API també recupera la llista de models en viu del proveïdor i actualitza les suggerències anteriors.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Aquesta és una pàgina de sistema de WooCommerce (Botiga, Carret, Pagament, etc.). El seu contingut és gestionat per WooCommerce — la puntuació reflecteix només senyals estructurals, no contingut SEO editable per l\'usuari.','This is the source page. Footnotes are edited directly in the block editor.'=>'Aquesta és la pàgina font. Les notes a peu s\'editin directament a l\'editor de blocs.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Aquesta clau actualment la proporciona un servidor %s i no es pot eliminar aquí. Introdueix una nova clau a dalt per substituir-la amb un valor de base de dades.','This language is protected and cannot be uninstalled.'=>'Aquest idioma està protegit i no es pot desinstal·lar.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Aquest idioma coincideix amb la localització de la instància de WordPress i no es pot desinstal·lar.','Tier'=>'Nivell','Tip: to reset a model to the built-in default, clear the field and save.'=>'Consell: per restablir un model a la configuració predeterminada, buida el camp i desa.','Title'=>'Títol','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Títol 15 pts · Meta descripció 20 pts · Comptador de paraules 15 pts · Títols 20 pts · Imatges 10 pts · Enllaços 10 pts. Límits de SERP per al títol 60 caràcters; meta 120–210 caràcters; advertència de comptador de paraules per sota de 300, error per sota de 100; H2 necessari; enllaços interns obligatoris.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'El títol té %1$d caràcters — pot ser truncat als SERPs (intenta que sigui menys de %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'El títol té només %d caràcters — intenta arribar a almenys 10 caràcters.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Regles de puntuació del títol (tots els perfils): fallar si està buit; advertir si té menys de 10 caràcters; advertir si només té una paraula; advertir si és més llarg que el límit SERP del perfil (60 caràcters per a Bloc, 70 per a Producte/Pàgina de destinació); ok si té almenys 10 caràcters, almenys 2 paraules, i dins del límit SERP.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Per utilitzar un secret d\'encriptació personalitzat (en lloc del valor derivat wp_salt), afegeix això a wp-config.php:','Today'=>'Avui','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Consum de tokens agrupat per funció, proveïdor i model. Registrat en cada trucada AI exitosa; les proves de connexió pings s\'exclouen perquè no distorsionin els totals.','Token usage'=>'Ús de tokens','Tone'=>'Tono','tone'=>'tono','Tone:'=>'Tono:','Too many AI requests. Please retry in %d seconds.'=>'Massa sol·licituds d\'AI. Torna-ho a provar en %d segons.','Total'=>'Total','Total tokens'=>'Tokens totals','Translate'=>'Tradueix','Translate / Revise'=>'Tradueix / Revisa','Translate / Revise block'=>'Bloc de traducció / revisió','Translate all'=>'Tradueix tot','Translate all %s terms (AI)'=>'Tradueix tots els termes %s (AI)','Translate all categories (AI)'=>'Tradueix totes les categories (AI)','Translate all labels (AI)'=>'Tradueix totes les etiquetes (AI)','Translate all tags (AI)'=>'Tradueix totes les etiquetes (AI)','Translate all terms (AI)'=>'Tradueix tots els termes (AI)','Translate chunk'=>'Traducció de fragment','Translate Content'=>'Contingut de traducció','Translate missing'=>'Traducció manca','Translate page…'=>'Tradueix la pàgina…','Translated content'=>'Contingut traduït','Translated Labels'=>'Etiquetes traduïdes','Translated Names'=>'Noms traduïts','Translated title'=>'Títol traduït','Translated to:'=>'Traduit a:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traduit. Revisa a l\'Editor del lloc — els enllaços interns, URLs de navegació i eslògans de plantilles no s\'actualitzen automàticament.','Translating…'=>'Traduint…','Translation Caching'=>'Caché de traducció','Translation caching'=>'Caché de traducció','Translation failed. Check the browser console.'=>'La traducció ha fallat. Comproveu la consola del navegador.','Translation found but permalink could not be generated'=>'S\'ha trobat la traducció però no s\'ha pogut generar l\'enllaç permanent','Translation Limits'=>'Límit de traducció','Translation Limits & Behavior'=>'Límit de traducció i comportament','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Límits de traducció: controla quins rols d\'usuari poden activar la traducció AI i estableix un pressupost mensual de tokens. Superar el pressupost suspèn les trucades AI fins que el mes es reiniciï.','Translation Memory'=>'Memòria de traducció','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'La memòria de traducció desa els resultats de l\'AI per hash de contingut, parell d\'idiomes, proveïdor i model. Editar una publicació invalida l\'entrada de la memòria cau perquè la propera trucada de traducció obtingui un resultat fresc.','Translation Memory cleared. %d cached block was removed.'=>'Memòria de traducció buida. %d bloc de memòria cau eliminat.' . "\0" . 'Memòria de traducció buida. %d blocs de memòria cau eliminats.','Translation Memory setting saved.'=>'Configuració de la memòria de traducció guardada.','Translation workflow'=>'Flux de treball de traducció','Translation, Content Generator'=>'Traducció, Generador de contingut','Treat H2 as H1 equivalent'=>'Tracta H2 com a equivalent a H1','Type'=>'Tipus','Uli Hake'=>'Uli Hake','Unexpected provider error (HTTP %d).'=>'Error inesperat del proveïdor (HTTP %d).','Uninstall %s'=>'Desinstal·la %s','Uninstall Behaviour'=>'Comportament de desinstal·lació','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Comportament de desinstal·lació: controla què s\'elimina quan s\'elimina el plugin de Plugins → Plugins instal·lats → Elimina. Els ajustos del plugin i les memòries cau d\'AI sempre s\'eliminan. Les assignacions de llengua, les relacions de traducció, les metadescripcions, el glossari i la Memòria de Traducció es mantenen per defecte perquè una desinstal·lació o reinstal·lació accidentals puguin continuar on ho van deixar. Activa "Elimina les dades de contingut a la desinstal·lació" només quan estiguis eliminant completament el suport multilingüe del lloc — això no es pot desfer.','Uninstall setting saved.'=>'Configuració de desinstal·lació desada.','unknown error'=>'error desconegut','Unknown provider.'=>'Proveïdor desconegut.','Unknown search engine.'=>'Motor de cerca desconegut.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'A diferència de hreflang — on LF sempre sobreescriu altres plugins perquè no poden conèixer la vostra configuració multilingüe — Open Graph és diferent: Yoast, Rank Math i plugins similars ja emeten etiquetes OG correctes per al vostre contingut. Duplicar-les no afegeix valor. En mode automàtic, LF detecta plugins SEO actius i afegeix només allò que no poden proporcionar: og:locale (idioma actual) i og:locale:alternate (tots els altres idiomes configurats).','Unlimited'=>'Il·limitat','Up'=>'Amunt','Upload .mo file'=>'Puja arxiu .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Puja arxius .mo compilats per substituir les cadenes de plugins de tercers per a idiomes específics — per exemple, una traducció personalitzada de VikBooking que utilitza "apartament" en lloc de "habitació". Els arxius han de seguir la convenció de nomenclatura de WordPress: {textdomain}-{locale}.mo (p. ex. vikbooking-ca.mo). Es guarden a la carpeta d\'uploads i sobreviuen a les actualitzacions del plugin.','Upload Override'=>'Puja substitució','URL could not be mapped to a post — check the link target exists'=>'L\'URL no es pot mapar a una publicació — comprova que l\'objectiu del enllaç existeix','URL structure'=>'Estructura d\'URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Estructura d\'URL: mode de prefix de camí (example.com/de/) no requereix canvis al servidor. Mode de subdomini (de.example.com) requereix un registre DNS comodí, un certificat SSL comodí i un canvi de configuració del servidor web — vegeu la guia de configuració del servidor.','URL to enter'=>'URL per introduir','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Utilitza la compartició nativa quan estigui disponible; recorre a copiar al porta-retalls. Recomanat per defecte per als botons "Compartir".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Utilitza les pestanyes a la part superior d\'aquesta pàgina per configurar cada àrea. Els canvis a la pestanya Router tenen efecte immediatament; els canvis a les claus d\'AI i configuracions de model s\'apliquen a la propera sol·licitud d\'AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Taula de terminologia gestionada per l\'usuari per parells d\'idiomes. Les entrades s\'afegeixen a la sol·licitud del sistema de traducció perquè la IA utilitzi termes preferits de manera consistent — crític per al vocabulari de domini ("kWp", "PPA", "punt d\'interconnexió"), noms de marca que no s\'han de traduir, i frases reguladores estandarditzades. Els camps de llengua són opcionals: deixa en blanc "Llengua d\'origen" per aplicar l\'entrada independentment de l\'idioma de traducció; deixa en blanc "Llengua de destinació" per aplicar-la a totes les llengües de destinació a la vegada.','Using custom meta description.'=>'Utilitzant una meta descripció personalitzada.','Using LF AI meta description.'=>'Utilitzant la meta descripció LF AI.','Value source'=>'Origen del valor','Version'=>'Versió','View'=>'Visualitza','View built-in default'=>'Visualitza el valor predeterminat integrat','View current robots.txt'=>'Visualitza el robots.txt actual','View details'=>'Visualitza detalls','View Lingua Forge details'=>'Visualitza detalls de Lingua Forge','Visit plugin site'=>'Visita el lloc del plugin','Warning:'=>'Avís:','WcPageBridge active'=>'WcPageBridge actiu','WebSite'=>'WebSite','WebSite — front page / blog index'=>'WebSite — pàgina principal / índex del blog','What LF provides — and collision avoidance'=>'El que proporciona LF — i evitació de col·lisions','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'El que proporciona LF: etiquetes hreflang per a cada idioma configurat, etiquetes Open Graph i Twitter Card amb og:locale i og:locale:alternate, Schema.org JSON-LD amb anotacions inLanguage, i un mapa del lloc multilingüe dedicat a /lf-sitemap.xml amb entrades xhtml:link alternatives per a tots els grups de traducció.','When another SEO plugin is installed'=>'Quan s\'instal·la un altre plugin SEO','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Quan s\'activa el registre de depuració (mitjançant el commutador de baix o definint LINGUAFORGE_AI_DEBUG a wp-config.php), les funcions de traducció de la plantilla i de traducció FSE escriuen les seves sol·licituds i respostes d\'AI en brut a disc per a la resolució de problemes. Utilitzeu aquesta secció per monitoritzar aquesta sortida i esborrar-la un cop tingueu el que necessiteu — els arxius poden créixer ràpidament en pàgines grans. Configureu el directori de destinació mitjançant el filtre linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Quan s\'activa, els visitants per primera vegada sense cookie de llengua i sense prefix de llengua a l\'URL són redirigits a la versió de llengua més propera. La redirecció s\'ignora si la llengua preferida del navegador no està entre les llengües actives del router. Un cop un visitant selecciona una llengua mitjançant el commutador, la cookie pren prioritat i l\'encapçalament del navegador s\'ignora en futures visites.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Quan s\'activa, el mapa del lloc de Lingua Forge emet els següents metatags addicionals a les pàgines de producte: og:type=product, og:price:amount, og:price:currency, og:availability, i els seus equivalents de l\'espai de noms product: utilitzats per Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Quan s\'activa, l\'URL del mapa del lloc s\'anuncia automàticament en robots.txt i la memòria cau s\'actualitza quan s\'emmagatzema contingut traduït.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Quan el perfil de Bloc requereix un H2 i no en troba cap, l\'anàlisi primer comprova els subtítols H3 abans d\'emetre una advertència. Els blocs d\'acordió i Detalls per defecte utilitzen H3 per als seus encapçalaments; aquests H3 s\'accepten com a estructura vàlida i produeixen un resultat correcte, no una advertència.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Quan l\'idioma del lloc WP no sigui un idioma de contingut: les consultes de productes de WooCommerce no retornaran resultats en tots els blocs de catàleg; la delegació d\'imatges de productes falla; totes les consultes de contingut filtrat per idioma es trencaran; el canviador d\'idioma pot mostrar una opció d\'idioma no de contingut espúria. Si veus una alerta de configuració en vermell a la part superior de la pestanya Router o System, corregeix primer l\'idioma del lloc.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Quan Yoast SEO, Rank Math, All in One SEO, o SEOPress estan actius, Lingua Forge suprimeix automàticament la seva sortida hreflang mitjançant filtre. Els plugins SEO generals produeixen hreflang basat en una estructura d\'URL d\'un sol idioma i no poden tenir en compte la vostra configuració de rutes multilingües; la sortida de LF sempre és correcta.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Quin nivell de model utilitzar per a la traducció de pàgina completa. La qualitat utilitza el model configurat a la taula de models anterior i es recomana per a traduccions precises i de llarg format. Canvieu a Light només si la velocitat o el cost són la prioritat i el contingut és curt.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Mentre està actiu, el plugin mu gestiona el conjunt bàsic d\'etiquetes OG i LF emet només etiquetes de localització (mode automàtic). Eliminar-lo canvia LF al mode OG complet automàticament.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce no està actiu.','WooCommerce page translations'=>' Traduccions de pàgines de WooCommerce','WooCommerce product price'=>'Preu del producte de WooCommerce','WooCommerce SEO settings saved.'=>'Configuració SEO de WooCommerce desada.','WooCommerce store currency'=>'Moneda de la botiga WooCommerce','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Les pàgines de sistema de WooCommerce (Botiga, Carret, Pagament, El meu compte) estan excloses — el seu contingut és gestionat per WooCommerce i no pot ser millorats mitjançant edicions SEO.','WooCommerce version'=>'Versió de WooCommerce','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'Versió de WooCommerce, mode d\'emmagatzematge de comandes (CPT / HPOS / compartit), i una taula de cobertura de traducció per idioma per a les quatre pàgines integrades de WC (Botiga, Carret, Pagament, El meu compte).','Word count'=>' Comptador de paraules','WordPress version'=>'Versió de WordPress','WP core canonical active (hreflang disabled)'=>'Canonical del nucli de WP actiu (hreflang desactivat)','WP instance language'=>'Llengua de la instància de WP','WP site language requirement'=>'Requisit d\'idioma del lloc WP','WP-CLI reference'=>'Referència WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Escriu indicacions i respostes d\'AI al disc per a la resolució de problemes','XML Sitemap'=>'Mapa del lloc XML','Yes'=>'Sí','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'També podeu definir claus com a constants o variables d\'entorn (per exemple, en wp-config.php). Aquestes fonts s\'utilitzen automàticament com a reserva quan no s\'emmagatzema cap clau de base de dades.','You do not have permission to manage these settings.'=>'No teniu permís per gestionar aquestes configuracions.','You do not have permission to read this post.'=>'No teniu permís per llegir aquesta publicació.','{n} stale path(s)'=>'{n} camí(s) obsolet(s)','~%d min read'=>'~%d min de lectura' . "\0" . '~%d min de lectura','— AI features are disabled.'=>'— Les funcionalitats d\'IA estan desactivades.','— Any source language —'=>'— Qualsevol idioma d\'origen —','— Any target language —'=>'— Qualsevol idioma de destinació —','— Any target —'=>'— Qualsevol destinació —','— Any —'=>'— Qualsevol —','— Auto-detect —'=>'— Detecció automàtica —','— auto-detect —'=>'— detecció automàtica —','— Deferred to plugin'=>'— D\'atribució al plugin','— Disabled'=>'— Desactivat','— Not detected'=>'— No detectat','— select a language —'=>'— selecciona un idioma —','← Back'=>'← Enrere','↑ Detected from current post'=>'↑ Detectat a la publicació actual','→ Locale tags only (manual setting)'=>'→ Etiquetes de localització només (configuració manual)','→ Locale tags only — deferring base OG to plugin'=>'→ Etiquetes de localització només — ajornant la base OG al plugin','↺ Re-translate'=>'↺ Re-tradueix','↺ Refine'=>'↺ Refinar','↺ Refresh'=>'↺ Actualitza','↺ Refresh AI Analysis'=>'↺ Actualitza l\'anàlisi d\'AI','↺ Refreshing…'=>'↺ Actualitzant…','⚠ Borderline'=>'⚠ Limítrof','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ No s\'han trobat publicacions <strong>{lang}</strong>. Assegureu-vos que totes les publicacions traduïdes tenen la seva metadada de llengua configurada com a <strong>{lang}</strong> a la metabox de llengua.','⚠ No changes'=>'⚠ Cap canvi','⚠ No changes — re-scan?'=>'⚠ Cap canvi — reescanejar?','✅ Fixed ({n})'=>'✅ Corregit ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ No s\'han trobat enllaços trencats ni discrepàncies de plantilla per a <strong>{lang}</strong>. S\'ha escanejat <strong>{scanned}</strong> publicació(s) i pàgina(s) — totes les comprovacions han passat. Els enllaços de la plantilla (capçalera, peu de pàgina, barra lateral) no s\'inclouen aquí — utilitzeu el botó de Reparar parts de plantilla per comprovar-los per separat.','✅ Template fixed'=>'✅ Plantilla corregida','✓ %s notified successfully.'=>'✓ %s notificat amb èxit.','✓ Active'=>'✓ Actiu','✓ Active at /lf-sitemap.xml'=>'✓ Actiu a /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Actiu — %d entrada d\'URL amb alternants de llengua' . "\0" . '✓ Actiu — %d entrades d\'URL amb alternants de llengua','✓ Active — full OG + Twitter Cards'=>'✓ Actiu — cartes OG + Twitter completes','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Actiu — només etiquetes de localització (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Totes les parts creades.','✓ All templates created.'=>'✓ Totes les plantilles creades.','✓ All translated.'=>'✓ Totes traduïdes.','✓ Configured'=>'✓ Configurat','✓ Connection OK'=>'✓ Connexió OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Contingut generat — vegeu la sobreposició per revisar, perfeccionar i aplicar.','✓ Done'=>'✓ Fet','✓ Enabled'=>'✓ Activat','✓ Good length'=>'✓ Bona longitud','✓ Hreflang active'=>'✓ Hreflang actiu','✓ In safe storage'=>'✓ En emmagatzematge segur','✓ Language installed.'=>'✓ Idioma instal·lat.','✓ LF outputs'=>'✓ Sortides LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Sortides LF Article / WebPage / WebSite','✓ LF outputs full OG + Twitter Cards'=>'✓ Sortides LF — OG complet + Twitter Cards','✓ LF outputs — plugin hreflang suppressed'=>'✓ Sortides LF — plugin hreflang suprimit','✓ Links fixed.'=>'✓ Enllaços arreglats.','✓ Nav refs fixed.'=>'✓ Referències de navegació arreglades.','✓ Parts fixed.'=>'✓ Parts arreglades.','✓ Pattern translated.'=>'✓ Patró traduït.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Fitxer robots.txt físic trobat. La directiva Sitemap de LF està present.','✓ Refined — review the updated draft above.'=>'✓ Refinat — revisa l\'esborrany actualitzat anteriorment.','✓ Translation saved'=>'✓ Traducció desada','✓ WP core canonical removed'=>'✓ Canonical del nucli WP eliminat','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s de ping ha fallat. L\'URL del mapa del lloc encara s\'anuncia en robots.txt — el motor de cerca el descobrirà en la seva propera exploració.','✗ Disabled'=>'✗ Desactivat','✗ Error:'=>'✗ Error:','✗ Failed:'=>'✗ Fallat:','✗ Not configured'=>'✗ No configurat','✗ Too long'=>'✗ Massa llarg','✗ Too short'=>'✗ Massa curt','❌ Failed'=>'❌ Fallat','📄 Wrong template'=>'📄 Plantilla incorrecta','📍 Stale path (page moved)'=>'📍 Camí obsolet (pàgina moguda)']];
